'use strict';
(function () {
  const E = LANG === 'en', Q = [{"id":82912,"giver":"【工人】乔治","to":"【工人】乔治","type":"kill","target":"☆吸血仙子","count":20,"sc":"寂静林地","lv":67,"rw":{"gold":102,"items":[]},"tr":["Kan Ver!","Ne zaman Sessiz Koru'ya odun kesmeye gitsem şu ☆Kan Emici Periler kanımı emiyor. Kanım o kadar mı lezzetli? Şimdi kan vermenin tadına onlar baksın!","Kabul","Sen de kan verdin mi?","Hah hah, sonunda kanın bedelini ödediler!"],"en":["Give Blood!","Whenever I go logging in the Silent Woodland those ☆Bloodsucking Fairies drain my blood. Is it really that tasty? Now let them have a taste of giving blood!","Accept","Have you given blood too?","Ha ha, they finally paid the price in blood!"]},{"id":82913,"giver":"【美女炼金师】爱丽丝","to":"【美女炼金师】爱丽丝","type":"kill","target":"暗影巨魔","count":20,"sc":"寂静林地","lv":67,"rw":{"gold":153,"items":[["30024",1]]},"tr":["Trollerin Misillemesi","George Gölge Trollerini defalarca rahatsız etti; öfkelendiler ve misillemeye hazırlanıyorlar. Onlar saldırmadan planlarını bozmanı istiyorum. Birkaç trol öldür ki akılları başlarına gelsin.","Kabul","Tam bir baş belası.","Harika, planlarını durdurdun."],"en":["The Trolls Strike Back","George kept harassing the Shadow Trolls until they got angry, and now they are preparing to strike back. Ruin their plan before they do. Kill some trolls so they learn to behave.","Accept","What a troublemaker.","Wonderful, you stopped their plan."]},{"id":82914,"giver":"【美女炼金师】爱丽丝","to":"【工人】乔治","type":"talk","req":82913,"rw":{"gold":91,"items":[["30419",10],["30484",10]]},"tr":["George'u Uyar","George'a söyle, bir daha trollere bulaşmasın. Yoksa generale söylerim, ömrünün sonuna kadar trollerle yaşar.","Kabul","Ona ilet lütfen.","Ah, işin bu kadar büyüyeceğini düşünmemiştim. Uyarın için sağ ol."],"en":["A Warning for George","Tell George to stop provoking the trolls, or I will tell the General and he can live with the trolls for the rest of his life.","Accept","Pass it on to him.","Oh, I never thought it would get this serious. Thanks for the warning."],"lv":67},{"id":82915,"giver":"【兽医】詹姆斯","to":"【兽医】詹姆斯","type":"collect","target":"林地夜行者","count":10,"sc":"寂静林地","lv":67,"chance":0.5,"rw":{"gold":109,"items":[["37529",1],["30024",1]]},"tr":["Gece Avcısı Zehri","Son günlerde art arda zehirlenmeler oluyor. Koru Gece Avcılarının ısırdığından şüpheleniyorum. Panzehir yapabilmem için bana onların zehrinden topla.","Kabul","Sakın ısırılma.","Harika, hemen panzehiri hazırlamalıyım.","Gece Avcısı Zehri"],"en":["Nightstalker Venom","There has been a string of poisonings lately. I suspect bites from Woodland Nightstalkers. Collect some of their venom so I can make an antidote.","Accept","Do not get bitten.","Great, I must prepare the antidote at once.","Nightstalker Venom"]},{"id":82916,"giver":"【蠢蛋将军】米斯特","to":"【蠢蛋将军】米斯特","type":"kill","target":"☆恐惧卫士","count":20,"sc":"地下庙宇","lv":50,"rw":{"gold":102,"items":[["30419",10],["30484",10]]},"tr":["Korku Muhafızları","Tarikat Üssü'ndeki ☆Korku Muhafızlarına dikkat et; aklını bulandırır, soydaşları birbirine kırdırırlar. İnancını sağlam tutarsan onları yenersin.","Kabul","Sakın beynini yıkamalarına izin verme.","☆Korku Muhafızlarını yendin."],"en":["Fear Guards","Beware the ☆Fear Guards of the Cult Base. They cloud your mind and turn kin against kin. Keep your faith firm and you will defeat them.","Accept","Do not let them brainwash you.","You defeated the ☆Fear Guards."]},{"id":82917,"giver":"森林警卫官","to":"森林警卫官","type":"kill","target":"织网毒蜘蛛","count":30,"sc":"罗网林地","lv":69,"rw":{"gold":115,"items":[["30024",1]]},"tr":["Örümcek Ailesi (1)","Ağlı Koru'da büyük bir tehdit var: kraliçeleri ordu topluyor. İlk işimiz bu toplanmayı engellemek. Güç peşindeki Ağ Ören Zehirli Örümcekler kraliçeye katılıyor; sayılarını azaltmalısın.","Kabul","Örümceklerin ailesi kalabalıktır.","İyi iş çıkardın. Sıradaki adıma geçelim."],"en":["The Spider Family (1)","A great threat lurks in the Webbed Woodland: their queen is gathering an army. Our first task is to stop it. The Webspinner Venom Spiders are joining her in search of power, so thin their numbers.","Accept","Spiders have very large families.","Well done. On to the next step."]},{"id":82918,"giver":"森林警卫官","to":"森林警卫官","type":"kill","target":"剑蜘蛛","count":30,"sc":"罗网林地","lv":69,"req":82917,"rw":{"gold":132,"items":[["30024",1]]},"tr":["Örümcek Ailesi (2)","Ağlı Koru'daki Kılıç Örümceği ordusu kraliçenin öncü birliği. Onları yok edersek kraliçenin yuvasını ele geçirebiliriz. Bu zorlu görevi başarabilir misin?","Kabul","Kılıç Örümceklerinin kılıcına dikkat et.","İyi iş çıkardın. Kraliçenin savunma hattını yardık."],"en":["The Spider Family (2)","The Sword Spider army of the Webbed Woodland is the queen's vanguard. Wipe them out and we can take her nest. Can you handle this hard task?","Accept","Watch out for the Sword Spiders' blades.","Well done. We have broken through the queen's defenses."]},{"id":82919,"giver":"森林警卫官","to":"森林警卫官","type":"kill","target":"☆蜘蛛护卫","count":10,"sc":"罗网林地","lv":69,"req":82918,"rw":{"gold":80,"items":[["30419",10],["30484",10]]},"tr":["Örümcek Ailesi (3)","Lanet olsun, şu ☆Örümcek Muhafızlar da nereden çıktı? Bu son savunma hattı olmalı; kraliçeyle yüzleşmek üzereyiz. Bu hattı ancak sen yarabilirsin.","Kabul","Tehdit bitmek üzere.","Sonunda kraliçeyle yüzleşeceğiz."],"en":["The Spider Family (3)","Damn it, where did those ☆Spider Guards come from? This must be the last line of defense. We are about to face the queen, and only you can break through.","Accept","The threat is almost gone.","At last we will face the queen."]},{"id":82920,"giver":"森林警卫官","to":"森林警卫官","type":"kill","target":"☆【欺诈女王】科琳娜","count":1,"sc":"罗网林地","lv":69,"req":82919,"rw":{"gold":30,"items":[]},"tr":["Örümcek Ailesi (4)","Sonuna geldik. Hilekâr Kraliçe ile son savaşı yapacağız. Hazır mısın?","Kabul","Korktun mu?","Sonunda kraliçeyi yendik."],"en":["The Spider Family (4)","We have reached the end. It is time for the final battle with the Deceiver Queen. Are you ready?","Accept","Are you scared?","We have finally defeated the queen."]},{"id":82922,"giver":"【美女炼金师】爱丽丝","to":"【美女炼金师】爱丽丝","type":"kill","target":"堕落学者","count":15,"sc":"迷途林地","lv":71,"rw":{"gold":122,"items":[]},"tr":["Yozlaşmış Bilginler","Yozlaşmış Bilginler büyüleriyle bütün Kayıp Koru'yu bozdu: bitkiler çürüyor, hayvanlar değişiyor. Bana yardım et, o bilginleri öldür; canlılar daha fazla yozlaşmasın.","Kabul","Sakın orada sen de yozlaşma.","Harika, onları kurtardın."],"en":["Fallen Scholars","The Fallen Scholars have corrupted the whole Lost Woodland with their sorcery. Plants are rotting and animals are mutating. Help me: kill those scholars before more creatures fall.","Accept","Do not fall there yourself.","Wonderful, you saved them."]},{"id":82923,"giver":"【兽医】詹姆斯","to":"【兽医】詹姆斯","type":"collect","target":"堕落学者","count":10,"sc":"迷途林地","lv":71,"chance":0.5,"rw":{"gold":107,"items":[["39503",1],["30024",1]]},"tr":["Bilgin Cübbesi","Derler ki Kayıp Koru'daki Yozlaşmış Bilginlere hiçbir zehir işlemezmiş. Sırları ne? İpucunu cübbelerinde arayacağım. Bana birkaç tane getirebilir misin?","Kabul","Hekimliğim çok iyidir.","Bana biraz zaman ver, incelemeye başlıyorum.","Bilgin Cübbesi"],"en":["Scholar's Coat","They say no poison can harm the Fallen Scholars of the Lost Woodland. What is their secret? I want to look for clues in their coats. Can you bring me a few?","Accept","I am a very skilled healer.","Give me some time, I will start my research.","Scholar's Coat"]},{"id":82924,"giver":"森林警卫官","to":"森林警卫官","type":"kill","target":"灵魂收割者","count":10,"sc":"鲜血庙宇","lv":60,"rw":{"gold":140,"items":[["30024",1]]},"tr":["Ruhları Koru","Tarikat Üssü'nde Ruh Biçiciler insan ruhlarını acımasızca yok ediyor. Ruhları korumalıyız; bunun en iyi yolu Ruh Biçicileri yok etmek. Onlarla yüzleşecek yüreğin var mı?","Kabul","Ruhuna dikkat et.","Yardımın sayesinde ruhları koruduk."],"en":["Guard the Souls","In the Cult Base the Soul Reapers are mercilessly erasing human souls. We must guard the souls, and the best way is to destroy the reapers. Do you dare to face them?","Accept","Mind your soul.","Thanks to you, we kept the souls safe."]},{"id":82925,"giver":"【工人】乔治","to":"【工人】乔治","type":"kill","target":"无脑僵尸","count":20,"sc":"迷途林地","lv":71,"rw":{"gold":99,"items":[["30419",10],["30484",10]]},"tr":["Beyinsiz Zombiler","Heh heh, şu zombilerle oynamaya bayılırım; başsız sinekler gibi oraya buraya koşarlar. Beyinleri yok, hepsi ahmak. Artık bu bölgeden yok olmalarını istiyorum. Ne yapacağını biliyorsun, değil mi?","Kabul","Zombilere de ki: gelin biraz oynayalım.","Hah hah, gerçekten beyinleri yokmuş."],"en":["Brainless Zombies","Heh heh, I love playing with those zombies. They run around like headless flies. No brains, all idiots. Now I want them gone from this area. You know what to do, right?","Accept","Tell the zombies: come and play for a while.","Ha ha, they really have no brains."]},{"id":82926,"giver":"【兽医】詹姆斯","to":"【兽医】詹姆斯","type":"collect","target":"☆仙子邪术师","count":10,"sc":"迷途林地","lv":71,"chance":0.5,"rw":{"gold":82,"items":[]},"tr":["Büyü Tozu","Her derde deva bir ilaç malzemesi buldum: Kayıp Koru'daki perilerin üstünde. Onlardan biraz toz getirebilirsen George'un bel ağrısını iyileştirebilirim.","Kabul","Her derde deva bir iksir yapacağım.","Evet, işte bu toz.","Büyü Tozu"],"en":["Sorcery Dust","I have found an ingredient that cures everything, and the fairies of the Lost Woodland carry it. Bring me some of their dust and I can cure George's back pain.","Accept","I am going to make a cure-all potion.","Yes, this is the dust.","Sorcery Dust"]},{"id":82927,"giver":"【兽医】詹姆斯","to":"【工人】乔治","type":"talk","req":82926,"rw":{"gold":53,"items":[["30024",1]]},"tr":["İksiri Dene","Hah hah, başardım! Şimdi bu iksiri George'a götür, tadına baksın. İçtiği an bel ağrısı geçecek.","Kabul","Çabuk, içsin şunu.","(George iksiri bir dikişte içti) Aman tanrım, bu zehir mi? Ne kadar da kötü!"],"en":["Taste Test","Ha ha, it worked! Take this potion to George and let him taste it. The moment he drinks it, his back pain will be gone.","Accept","Hurry, make him drink it.","(George gulps the potion down) Good grief, is this poison? It tastes awful!"],"lv":67},{"id":82928,"giver":"【工人】乔治","to":"【兽医】詹姆斯","type":"talk","req":82927,"rw":{"gold":48,"items":[]},"tr":["Bana Eziyet Etmeyin!","Yalvarırım bana eziyet etmeyi bırakın! Çok acı çekiyorum! Beni susturmak mı istiyorsunuz? Aaaah! (George epey acı çekiyor gibi görünüyor.)","Kabul","Bırak beni! Öleyim daha iyi!","Hah hah hah, yine olmadı…"],"en":["Stop Tormenting Me!","I beg you, stop tormenting me! It hurts so much! Are you trying to silence me for good? Aaargh! (George looks like he is in real pain.)","Accept","Leave me alone! Just let me die!","Ha ha ha, failed again…"],"lv":67},{"id":82929,"giver":"【美女炼金师】爱丽丝","to":"【美女炼金师】爱丽丝","type":"collect","target":"污染者","count":10,"sc":"堕落林地","lv":70,"chance":0.5,"rw":{"gold":85,"items":[["30024",1]]},"tr":["Kirletici Cübbesi","Pis Kirleticiler! Ormanı bile bile yok ediyor, canlıları zehirliyorlar. Onları öldürmeme yardım eder misin? Yapabilirsen giydikleri cübbeleri getir, gücünü kanıtla.","Kabul","Sakın sana da bulaşmasınlar.","Harika, ne kadar çirkin olduklarını onlara göstereceğim.","Kirletici Cübbesi"],"en":["Defiler's Robe","Filthy Defilers! They ruin the forest on purpose and poison every living thing. Will you help me kill them? If you can, bring back the robes they wear to prove your strength.","Accept","Do not let them taint you.","Wonderful, I will show them how ugly they are.","Defiler's Robe"]},{"id":82930,"giver":"森林警卫官","to":"森林警卫官","type":"kill","target":"污染者","count":10,"sc":"堕落林地","lv":70,"rw":{"gold":72,"items":[["30419",10],["30484",10]]},"tr":["Kirliliği Önle","Yozlaşmış Koru'nun kirlenmesini önle! Kirleticileri durdur! Öldür!","Kabul","Sağ bırakma!","İyi iş çıkardın, orayı kurtarmalıyız."],"en":["Stop the Pollution","Stop the pollution of the Fallen Woodland! Stop the Defilers! Kill!","Accept","Leave none alive!","Well done, we must save that place."]},{"id":82931,"giver":"【工人】乔治","to":"森林警卫官","type":"talk","rw":{"gold":75,"items":[["30024",1]]},"tr":["Asıl Katil Kim","Kardeşim Paul öldürüldü. Orman Muhafız Subayı'na sorar mısın, katil kim? Kardeşimi öldürmeye kim cüret eder!","Kabul","Katili bulacağım!","Ne? George'un kardeşi mi öldürülmüş?"],"en":["Who Is the Killer","My brother Paul has been killed. Could you ask the Forest Guard Officer who did it? Who would dare to kill my brother!","Accept","I will find the killer!","What? George's brother was killed?"],"lv":67},{"id":82932,"giver":"森林警卫官","to":"【工人】乔治","type":"collect","target":"☆剧毒撕裂者","count":1,"sc":"堕落林地","lv":70,"chance":1,"req":82931,"rw":{"gold":132,"items":[["30024",1]]},"tr":["Katili Ara","Yılların tecrübesiyle söylüyorum, ☆Zehirli Parçalayıcılardan şüpheleniyorum. Çok gizli hareket ederler; görüş alanlarına girersen sonun gelmiş demektir. Kayıp Koru'dalar. Bir ipucu bulursan doğrudan George'a söyle.","Kabul","O yaratıklara dikkat et.","Aaah, Paul'un intikamını alacağım!","Paul'un Hatırası"],"en":["Find the Killer","From my years of experience, I suspect the ☆Venomous Rippers. They move in secret, and if they see you, your end has come. They are in the Lost Woodland. If you find a clue, tell George directly.","Accept","Be careful around those creatures.","Aaah, I will avenge Paul!","Paul's Keepsake"]},{"id":82933,"giver":"【工人】乔治","to":"【工人】乔治","type":"kill","target":"☆剧毒撕裂者","count":20,"sc":"堕落林地","lv":70,"req":82932,"rw":{"gold":107,"items":[["30419",10],["30484",10]]},"tr":["Kardeşimin İntikamı","Canım kardeşim, nasıl da feci öldün, hüüü… İntikamını alacağım. Dostum, sen olmasan kardeşimin ölümünün gerçeğini asla öğrenemezdim. Bir kez daha yardım et, o ☆Zehirli Parçalayıcıların hepsini öldür!","Kabul","Hüüü hüüü…","Sağ ol, hüüü hüüü…"],"en":["Revenge for My Brother","My dear brother, what a terrible death, boo-hoo… I will avenge you. Friend, without you I would never have learned the truth. Help me once more: kill every one of those ☆Venomous Rippers!","Accept","Boo-hoo…","Thank you, boo-hoo…"]},{"id":82934,"giver":"【蠢蛋将军】米斯特","to":"【兽医】詹姆斯","type":"talk","rw":{"gold":64,"items":[["30024",1]]},"tr":["Troller Don mu Giyer?","Çok tuhaf, buradaki troller don giyiyor?! James'e sorar mısın, bunun sebebi ne?","Kabul","Çirkin troller don giyiyor.","Benden ne istiyorsun?"],"en":["Do Trolls Wear Underpants?","How strange, the trolls here wear underpants?! Could you ask James what the reason is?","Accept","Ugly trolls in underpants.","What do you want from me?"],"lv":50},{"id":82935,"giver":"【兽医】詹姆斯","to":"【兽医】詹姆斯","type":"collect","target":"☆鬼巨魔","count":1,"sc":"堕落林地","lv":70,"chance":1,"req":82934,"rw":{"gold":58,"items":[["30024",1]]},"tr":["Don Topla","Onlardan birinin donunu bana getir, incelemek istiyorum. Yozlaşmış Koru'da yaşıyorlar.","Kabul","Ne tuhaf.","(Don mide bulandırıcı bir koku yayıyor) Bu da ne böyle.","Trol Donu"],"en":["Collect Underpants","Bring me the underpants of one of them, I want to study them. They live in the Fallen Woodland.","Accept","How odd.","(The underpants give off a sickening smell) What on earth is this.","Troll Underpants"]},{"id":82936,"giver":"【兽医】詹姆斯","to":"【蠢蛋将军】米斯特","type":"talk","req":82935,"rw":{"gold":58,"items":[["30024",1]]},"tr":["Gaz Bombası!!","Bu donu generale götür de trolleri inceleme sevdasından vazgeçsin. Bu resmen delilik.","Kabul","(James yere kustu) İğrenç.","Ah, çok pis kokuyor! Bu resmen gaz bombası!"],"en":["Stink Bomb!!","Take these underpants to the General so he gives up his idea of studying trolls. This is pure madness.","Accept","(James throws up on the floor) Disgusting.","Argh, it stinks! This is a real stink bomb!"],"lv":67},{"id":82937,"giver":"【蠢蛋将军】米斯特","to":"【蠢蛋将军】米斯特","type":"kill","target":"☆鬼巨魔","count":20,"sc":"堕落林地","lv":70,"req":82936,"rw":{"gold":55,"items":[["30419",10],["30484",10]]},"tr":["Belanızı Aradınız!!","Beni kızdırdılar, bu resmen belayı aramak! Şu ☆Hayalet Trollerin canı cehenneme!","Kabul","(General yere kustu) Bu gerçekten iğrenç.","Hah hah, iyi iş genç!"],"en":["Asking for Death!!","They made me angry, and that is asking for death! To hell with those ☆Ghost Trolls!","Accept","(The General throws up on the floor) This is truly disgusting.","Ha ha, well done, youngster!"]},{"id":81767,"giver":"森林警卫官","to":"森林警卫官","type":"kill","target":"凶恶蝙蝠","count":10,"sc":"传送回廊","lv":50,"rw":{"gold":200,"items":[["30024",1]]},"tr":["Vebalı Yarasalar","Sıkı savunmamız sayesinde ☆tarikatçılar buraya sızıp ortalığı karıştıramadı. Ama geceleri yeşil yarasalar ortaya çıkıyor. Belki de trollere hastalığı bulaştırıp onları değiştiren bu yarasalardır. Onları öldürürsek işler düzelebilir.","Kabul","Tarikat sandığımız kadar basit değilmiş.","Yarasalar temizlendi; troller artık kudurmayacak."],"en":["Plague Bats","Thanks to our tight defense the ☆cultists have never slipped out to cause trouble. But at night some green bats appear. Perhaps these bats infected the trolls and made them mutate. Kill the bats and things may take a turn for the better.","Accept","The cult is not as simple as we thought.","With the bats cleansed, the trolls will no longer go berserk."]},{"id":80476,"giver":"警卫卡鲁","to":"警卫卡鲁","type":"collect","target":"森林巨魔","count":10,"sc":"巨魔森林","lv":28,"chance":0.5,"rw":{"gold":113,"items":[["30033",5]]},"tr":["Anlaşılmaz Bir Merak","Şehir Beyi'nin tuhaf merakından şikâyet edecek değilim; bütün vaktim ormandaki şu canavarlarla, trollerle uğraşmakla geçiyor. Evet, bedenleri taş gibi olan bu yaratıklara karşı elimden pek bir şey gelmiyor. Onlarla aptalca güç yarıştırmak istemem. Bu işi denemek ister misin?","Kabul","Bu ormanın her yanı tuhaflık dolu.","Sakın bana fıkra anlatıp birbirlerinin boynuzlarını söktürdüğünü söyleme.","Trol Boynuzu"],"en":["A Peculiar Hobby","I will not complain about the Lord's odd hobby, because all my time goes to dealing with the monsters of this forest: the trolls. Yes, these rock-hard brutes leave me almost helpless, and I am not fool enough to match strength with them. Want to try this challenge?","Accept","Everything about this forest is strange.","Do not tell me you got them to pull out each other's horns by telling jokes.","Troll Horn"]},{"id":80474,"giver":"警卫卡鲁","to":"奔马城城主","type":"talk","req":80476,"rw":{"gold":60,"items":[["30033",5]]},"tr":["Uzun Yol","Elimden gelse seninle dönerdim ama görevim bununla bitmiyor. Geldiğin yoldan dön ve bunları Şehir Beyi'ne ver. Bu işi hâlâ hatırlıyor mu, onu da bilmiyorum.","Kabul","Burada fazla uzun kaldım.","Trol boynuzu mu? Bunlarla ne yapmak istediğimi hatırlamam biraz zaman alacak."],"en":["The Long Journey","If I could, I would go back with you, but my duties do not end here. Follow the road you came by and hand these to the Lord. I wonder if he even remembers this matter.","Accept","I have been here far too long.","Troll horns? I will need some time to remember what I wanted them for."],"lv":28},{"id":81741,"giver":"警卫卡鲁","to":"警卫卡鲁","type":"collect","target":"☆饥饿的巨魔","count":10,"sc":"巨魔森林","lv":28,"chance":0.5,"rw":{"gold":102,"items":[]},"tr":["Daha Çok Boynuz","Belki de dikkatimizi şu yeşil trollere vermeliyiz. Orman Trollerinden açıkça farklı gördüğüm tek şey bu. Git, bir dene.","Kabul","Orman Trollerinden daha saldırgan görünüyorlar.","Bunlarla Şehir Beyi memnun kalır sanırım.","Yeşil Boynuz"],"en":["More Horns","Perhaps we should turn our attention to those green trolls. That is the one clear difference from the Forest Trolls that I can see. Go and give it a try.","Accept","They seem more aggressive than the Forest Trolls.","With these, I think the Lord will be satisfied.","Green Horn"]},{"id":81742,"giver":"警卫卡鲁","to":"警卫卡鲁","type":"kill","target":"☆巨魔摧毁者","count":10,"sc":"巨魔森林","lv":28,"req":81741,"rw":{"gold":108,"items":[["30024",1]]},"tr":["Lanet Pusucular","Bu iri kıyım ahmakların pusu kurabileceği hiç aklıma gelmezdi; büyük bir keşif bu. Burada yıllardır yaşamanın verdiği çeviklik olmasa şimdi ardımdan ancak dua edebilirdin. Şu Yıkıcılara günlerini göstermeliyim.","Kabul","Onlarla baş etmek için kafa yorman gerek.","Yumruklarından nasıl kaçtın?"],"en":["Damned Ambushers","I never imagined these big oafs could set an ambush. What a discovery. Without the quick wits I gained from living here so long, you would now only be able to pray for me. I must teach those Destroyers a lesson.","Accept","You will need to use your head to deal with them.","How did you dodge their fists?"]},{"id":81743,"giver":"警卫卡鲁","to":"奔马城城主","type":"talk","req":81742,"rw":{"gold":70,"items":[["11242",1]]},"tr":["Dolgun Ücret","Altını sevmeyen yoktur; sana verdiğim iş kadar kolayı da yok. Biraz yorulman yeter, dolgun bir ücret alırsın. Daha ne düşünüyorsun, bu paketi Şehir Beyi'ne götür.","Kabul","Bu lanet yerden nefret ediyorum.","Vay, her gelişinde beni şaşırtıyorsun."],"en":["A Handsome Fee","Nobody dislikes gold, and no job is as easy as the one I am giving you. Just spend a little effort and you earn a handsome fee. Why hesitate? Take this package to the Lord.","Accept","I hate this damned place.","Wow, you surprise me every time you come."],"lv":28},{"id":82555,"giver":"民兵队长","to":"民兵队长","type":"kill","target":"野猪","count":5,"sc":"阳光森林","lv":7,"req":80004,"rw":{"gold":112,"items":[["30024",1]]},"tr":["Yaban Domuzu Derdi","Güneşli Orman'daki domuzlar gitgide çoğalıyor ve gündelik hayatımızı fena hâlde aksatıyor. Bu yaban domuzları çok saldırgandır. Bize biraz yaşam alanı açmalısın.","Kabul","Hâlâ burada ne arıyorsun?","İyi iş çıkardın genç."],"en":["Boar Trouble","The boars of the Sunny Forest keep multiplying and are seriously disrupting our daily life. These wild boars are very aggressive. I think you should clear some living space for us.","Accept","What are you still doing here?","Well done, youngster."]},{"id":81704,"giver":"民兵队长","to":"民兵队长","type":"kill","target":"毒蛇帮路匪","count":10,"sc":"阳光森林","lv":7,"req":82555,"rw":{"gold":139,"items":[["30024",1]]},"tr":["Engerek Çetesi","Guanlin Kasabası öteden beri oduncuklukla geçinir. Güçlerine güvenen bazı tembeller odun kesip dönen kasabalıları soymaya başladı! Son günlerde iş iyice azıttı; gelip geçen tüccarlar da zarar görüyor, kasabanın adı lekeleniyor. Git ve onları adalete teslim et.","Kabul","Lanet Engerek Çetesi, başlarına gelecek var!","Harika, görünen o ki elinden iş geliyor!"],"en":["The Viper Gang","Guanlin Town has always lived off logging. Some idlers who rely on their strength have begun robbing townsfolk on their way back from cutting wood! Lately it has gotten worse; passing merchants suffer too, and the town's reputation is ruined. Go and bring them to justice.","Accept","Damned Viper Gang, they have it coming!","Excellent, it seems you do have some skill!"]},{"id":81705,"giver":"民兵队长","to":"观林镇镇长","type":"talk","req":81704,"rw":{"gold":85,"items":[["30024",1]]},"tr":["Muhtara Müjde","Seni küçümsemişim. Kim bilir, belki bir gün benim gibi büyük bir milis komutanı olursun! Tecrübeme göre artık başarılarını muhtara anlatabilirsin.","Kabul","Gelecek vaat eden bir çocuk.","Bu harika! Tam da adama ihtiyacımız vardı!"],"en":["Report to the Mayor","It seems I underestimated you. Who knows, one day you might become a great militia captain like me! In my experience, it is time to report your great deeds to the Mayor.","Accept","A promising kid.","This is wonderful! We are short of hands!"],"lv":7},{"id":81706,"giver":"观林镇镇长","to":"观林镇镇长","type":"collect","target":"蜘蛛","count":5,"sc":"阳光森林北","lv":10,"chance":0.5,"req":81705,"rw":{"gold":168,"items":[["30024",1]]},"tr":["Aklını Kullan","Engerek Çetesi laftan anlamıyor; onlara acıyı tattırmalıyız! Güneşli Orman Kuzey'e git, birkaç örümcek öldür ve bana örümcek salgısı getir. Ne işe yarayacağını biz biliriz. (Muhtar tuhaf bir kahkaha attı.)","Kabul","Şu haydut Engerek Çetesi! Onlara gününü göstermezsem beni kolay lokma sanarlar!","Bu, planımızın ilk adımı.","Örümcek Salgısı"],"en":["Use Your Wits","The Viper Gang will not listen to reason, so we must make them suffer! Go to Sunny Forest North, kill some spiders and bring me spider slime. We have our uses for it. (The Mayor lets out a strange laugh.)","Accept","Those Viper Gang bandits! If I do not teach them a lesson, they will think I am a pushover!","This is the first step of our plan.","Spider Slime"]},{"id":81707,"giver":"观林镇镇长","to":"民兵队长","type":"kill","target":"毒蛇帮精英","count":10,"sc":"阳光森林南","lv":13,"rw":{"gold":121,"items":[["30024",1]]},"tr":["Engerek Çetesine Ceza","Tamam, zehri silahına sürdüm. Git, Engerek Çetesi Seçkinlerini kes; acı içinde ölsünler! Bitirince Milis Komutanı ile konuş. Adamlarım ceza yöntemlerime hayran kalsın!","Kabul","Ceza yöntemlerim hep pek ustacadır, öyle değil mi?","Muhtar böyle mi oldu…"],"en":["Punish the Viper Gang","Good, I have smeared the venom on your weapon. Go and cut down the Viper Gang Elites, and let them die in agony! When you are done, talk to the Militia Captain. I want my men to admire my methods of punishment!","Accept","My methods of punishment are always so clever, are they not?","So the Mayor has become like this…"]},{"id":81708,"giver":"观林镇镇长","to":"民兵队长","type":"kill","target":"恶作剧仙子","count":10,"sc":"阳光森林南","lv":13,"rw":{"gold":158,"items":[["30024",1]]},"tr":["Lanet Sinekler","Güneşli Orman Güney'de sinek kadar iğrenç Yaramaz Periler var; insanın sinirini bozuyorlar! Silahınla onlara beni kızdırmanın sonunu göster! Bitirince Milis Komutanı ile konuş. Adamlarım ceza yöntemlerime hayran kalsın!","Kabul","O iğrenç sinekler gücümü tatsın!","Ne kadar acımasızca!"],"en":["Hateful Flies","In Sunny Forest South there are Prankster Fairies as disgusting as flies, and they get on my nerves! Show them with your weapon what happens to those who anger me! When you are done, talk to the Militia Captain. I want my men to admire my methods of punishment!","Accept","Let those disgusting flies taste my power!","How cruel!"]},{"id":81643,"giver":"护民官","to":"护民官","type":"kill","target":"☆毒蛇帮虐杀者","count":8,"sc":"阳光森林东","lv":18,"rw":{"gold":169,"items":[]},"tr":["Engerek Çetesini Temizle","Engerek Çetesi artık Guanlin Kasabası'na zarar veremiyor. Bu fırsatı kaçırmayalım, hepsini Güneşli Orman'dan sürelim. Başaracağına inanıyorum! Geriye yalnızca ☆Engerek Çetesi Kasapları kaldı.","Kabul","Buraya bir daha adım atmasınlar.","Guanlin Kasabası'na huzurunu geri verdin, teşekkürler."],"en":["Clear Out the Viper Gang","The Viper Gang can no longer harm Guanlin Town, so let us seize this chance and drive them all out of the Sunny Forest. I believe you can do it! Only the ☆Viper Gang Butchers are left.","Accept","Do not let them set foot here again.","You have brought peace back to Guanlin Town. Thank you."]},{"id":81632,"giver":"护林游侠","to":"护林游侠","type":"kill","target":"☆精英护卫","count":5,"sc":"阳光森林东","lv":18,"rw":{"gold":130,"items":[["30024",1]]},"tr":["Seçkin Muhafızlar","Bu görev çok zorlu. Üstesinden gelip gelemeyeceğini en iyi sen bilirsin; ama gözlerinden kendine güvendiğini okuyorum, o yüzden sana inanıyorum. ☆Seçkin Muhafızlar Güneşli Orman Doğu'nun derinliklerinde.","Kabul","Umarım sağ salim dönersin.","Sandığımdan çok daha güçlüymüşsün!"],"en":["Elite Guards","This task is very hard. Only you know whether you can handle it, but I can see in your eyes that you are full of confidence, so I believe in you. The ☆Elite Guards are deep in Sunny Forest East.","Accept","I hope you come back safely.","You are much stronger than I imagined!"]},{"id":81626,"giver":"杰西","to":"护林游侠","type":"talk","rw":{"gold":102,"items":[["30016",5],["30019",5],["30024",1]]},"tr":["Kayıt","Hey, oradaki genç! Bu günlerde Guanlin Kasabası'nda çok eğlenceli bir etkinlik var. Seni Orman Korucusu'na önerdim bile; hemen git, kaydını yaptır.","Kabul","","Oo! Gerçekten güçlü görünüyorsun."],"en":["Sign Up","Hey, you there, youngster! Guanlin Town is holding a very interesting event these days. I have already recommended you to the Forest Ranger, so hurry and sign up with him.","Accept","","Oh! You really do look strong."],"lv":18},{"id":81627,"giver":"护林游侠","to":"护林游侠","type":"kill","target":"森林蝰蛇","count":10,"sc":"阳光森林南","lv":13,"req":81626,"rw":{"gold":112,"items":[["30016",5],["30019",5],["30024",1]]},"tr":["Büyük Yılan Avı","Bu etkinlikte Güneşli Orman'ın güneyindeki engerekler yok edilecek. Bu yaratıklar artık biz insanlardan korkmuyor. Git ve onlara insan gücünün ne kadar büyük olduğunu göster!","Kabul","Senden çok şey bekliyorum.","Evet! Beni hayal kırıklığına uğratmadın!"],"en":["The Great Snake Hunt","The goal of this event is to wipe out the vipers in the south of the Sunny Forest. These creatures no longer fear us humans. Go and show them how mighty human strength is!","Accept","I expect great things from you.","Yes! You did not disappoint me!"]},{"id":81628,"giver":"护林游侠","to":"杰西","type":"talk","req":81627,"rw":{"gold":72,"items":[["30016",5],["30019",5],["30024",1]]},"tr":["Jessie'ye Haber Ver","Bu etkinlikte çok başarılıydın ve büyük takdir topladın. Git, bunu Jessie'ye anlat. Seninle gurur duyacaktır.","Kabul","","Harikasın! Beklediğimin çok üstünde!"],"en":["Tell Jessie","You performed brilliantly in this event and earned high praise. Go and tell Jessie about it. She will surely be proud of you.","Accept","","You are amazing! Far beyond what I expected!"],"lv":18},{"id":80035,"giver":"疯子","to":"疯子","type":"kill","target":"森林蝰蛇","count":10,"sc":"阳光森林南","lv":13,"rw":{"gold":88,"items":[["30033",5],["30024",1]]},"tr":["Periler ve Yılanlar","Aaah, Güneşli Orman Güney'de neden bu kadar çok sinir bozucu yaratık var? Orada bir türlü rahat uyuyamıyorum. Sen, evet sen, başkasına bakma, sana diyorum: git, onların işini bitir.","Kabul","Hâlâ burada ne dikiliyorsun?","Oley! İyi iş!"],"en":["Fairies and Snakes","Aaah, why are there so many annoying creatures in Sunny Forest South? They never let me sleep in peace there. You, yes you, do not look at anyone else, I mean you: go and get rid of them for me.","Accept","Why are you still standing here?","Oh yeah! Nicely done!"]},{"id":81620,"giver":"护林游侠","to":"护林游侠","type":"collect","target":"☆毒蛇帮虐杀者","count":10,"sc":"阳光森林东","lv":18,"chance":0.5,"rw":{"gold":125,"items":[]},"tr":["Kasapların Zırhı","Guanlin milislerini güçlendirmek için onlara sağlam zırh yaptırmam gerek. Duyduğuma göre ☆Engerek Çetesi Kasaplarının giydiği zırh bu iş için çok iyiymiş. Haydi genç, bana birkaç tane getir.","Kabul","Bu zırhlar milisleri güçlendirmenin en önemli şartı.","Güzel, beni hayal kırıklığına uğratmadın.","Kasap Zırhı"],"en":["The Butchers' Armor","To strengthen the Guanlin militia I need to forge sturdy armor for them. I hear the armor worn by the ☆Viper Gang Butchers is an excellent choice. Go on, youngster, bring me some.","Accept","This armor is the key to making the militia stronger.","Good, you did not disappoint me.","Butcher Armor"]},{"id":81644,"giver":"民兵队长","to":"民兵队长","type":"collect","target":"☆精英护卫","count":5,"sc":"阳光森林东","lv":18,"chance":0.5,"rw":{"gold":98,"items":[]},"tr":["Seçkin Zırh","Güneşli Orman Doğu'daki ☆Seçkin Muhafızlar gitgide çoğalıyor. Oraya gidip zırhlarını toplamanı istiyorum; ne kadar çok olursa o kadar iyi. Vakit dar, çabuk git gel.","Kabul","Buradaki milisleri güçlü kılacağım.","Teşekkürler, bu kadarı yeter. Şimdi zırhları dövmeye başlayacağım.","Seçkin Zırh Parçası"],"en":["Elite Armor","The ☆Elite Guards in Sunny Forest East keep growing in number. I need you to go there and collect their armor, the more the better. Time is short, so be quick.","Accept","I will make the militia here strong.","Thank you, this is enough. Now I will start forging the armor.","Elite Armor Plate"]},{"id":81621,"giver":"护林游侠","to":"民兵队长","type":"talk","req":80039,"rw":{"gold":59,"items":[]},"tr":["Durumu Bildir","Milis Komutanı'na Kasapların püskürtüldüğünü söylemeni istiyorum. Umarım bundan sonraki işleri o düzenler.","Kabul","","Haber verdiğin için sağ ol. Posta güverciniyle üstlerime danışmam gerek."],"en":["Report In","Please tell the Militia Captain that the Butchers have been driven back. I hope he can arrange what comes next.","Accept","","Thank you for letting me know. I need to send a carrier pigeon and consult my superiors."],"lv":18},{"id":81622,"giver":"民兵队长","to":"护林游侠","type":"talk","req":81621,"rw":{"gold":71,"items":[]},"tr":["Yeni Görev","Bence şimdi gevşemenin sırası değil; en azından Engerek Çetesi meselesi tam çözülmedi. Sıradaki yeni görevin bu.","Kabul","","Hmm… Mesele gerçekten de tam çözülmüş değil."],"en":["A New Task","I do not think this is the time to relax. At the very least, the Viper Gang problem is not fully solved. That is your next task.","Accept","","Hmm… The matter really is not fully settled."],"lv":7},{"id":81648,"giver":"民兵队长","to":"护民官","type":"talk","rw":{"gold":119,"items":[]},"tr":["Guanlin'in Umudu","Kasaba huzursuz; hain Sadinman intikam planını hazırlamaya başladı. Guanlin Kasabası yok mu olacak? Bunu mutlaka engellemelisin. Çabuk, Halk Koruyucusu'na git ve bu işi görüş.","Kabul","","Genç, durum ciddi. Guanlin Kasabası'nı mutlaka kurtarmalısın."],"en":["The Hope of Guanlin","The town is in turmoil, and the traitor Sadinman has begun preparing his revenge. Is Guanlin Town about to be destroyed? You must stop this from happening. Quickly, go and discuss it with the Tribune.","Accept","","Youngster, the situation is grave. You must save Guanlin Town."],"lv":7},{"id":81649,"giver":"护民官","to":"民兵队长","type":"talk","req":81648,"rw":{"gold":118,"items":[["30024",1]]},"tr":["Guanlin'in Kurtarıcısı","Artık çok güçlendin; herkes seni Guanlin Kasabası'nın kurtarıcısı olarak görüyor. Burayı mutlaka kurtarmalısın, sana güveniyoruz. Milis Komutanı'na söyle, sana destek olsun; Sadinman mutlaka yok edilmeli.","Kabul","","Cesur genç, git ve bir mucize yarat."],"en":["The Savior of Guanlin","You have grown very strong, and everyone sees you as the savior of Guanlin Town. You must save this place, we are counting on you. Tell the Militia Captain to support you. Sadinman must be destroyed.","Accept","","Brave youth, go and work a miracle."],"lv":18},{"id":81650,"giver":"民兵队长","to":"民兵队长","type":"kill","target":"☆☆【叛徒】萨丁曼","count":1,"sc":"阳光森林东","lv":18,"req":81649,"rw":{"gold":16,"items":[]},"tr":["Sadinman'a Meydan Oku","Git, Sadinman'a meydan oku. Mutlaka sağ dön!","Kabul","Silahını al ve savaş!","Sadinman yenildi mi? Bu bir mucize! Sen kasabayı kurtaran kahramansın!"],"en":["Challenge Sadinman","Go and challenge Sadinman. Make sure you come back alive!","Accept","Take your weapon and fight!","Sadinman has been defeated? It is a miracle! You are the hero who saved the town!"]},{"id":81651,"giver":"民兵队长","to":"观林镇镇长","type":"talk","req":81650,"rw":{"gold":41,"items":[["10588",1]]},"tr":["Guanlin'in Kahramanı","Harika, sen bizim kahramanımızsın; Sadinman bir daha buraya saldırmaya cesaret edemez. Muhtara git, hak ettiğin ödülü verecek.","Kabul","","Vay! Demek herkesi kurtaran sensin; kahramanlar genç yaşta çıkarmış. Bu hak ettiğin ödül, al."],"en":["The Hero of Guanlin","Wonderful, you are our hero, and Sadinman will never dare attack this place again. Go to the Mayor, he will give you the reward you deserve.","Accept","","Well! So you are the one who saved everyone. Heroes truly do emerge young. This is the reward you deserve, take it."],"lv":7},{"id":80051,"giver":"观林镇镇长","to":"皇家骑士特使","type":"talk","req":81732,"rw":{"gold":206,"items":[]},"tr":["Kral'ın Fermanı","Bizim için o kadar çok şey yaptın ki hepsinin karşılığını veremeyiz. Senin gibi bir kahraman daha önemli yerlerde iş görmeli. Kral, Gümüşkartal Dükü'nün isyanındaki çıkmazı kırmak için Koşanat Şehri'nde maceracı topluyor. İşte bir tavsiye mektubu; bunu görünce değerini anlayacaklardır. Kendini göster!","Kabul","Tavsiye mektubunu Koşanat Şehri'ndeki Kraliyet Şövalye Elçisi'ne götür.","Guanlin muhtarının mektubu mu? Hoş geldin, yiğit; tam vaktinde geldin.","Tavsiye Mektubu"],"en":["The King's Decree","You've done so much for us that we can never repay it all. A hero like you should serve where it matters more. The King is gathering adventurers in Galloping Horse City to break the deadlock in the Silver Eagle Duke's rebellion. Here's a letter of recommendation; when they see it, they'll understand your worth. Make us proud!","Accept","Take the letter of recommendation to the Royal Knight Envoy in Galloping Horse City.","A letter from the mayor of Guanlin? Welcome, hero; you've come just in time.","Letter of Recommendation"],"lv":10},{"id":81618,"giver":"民兵队长","to":"民兵队长","type":"kill","target":"毒蛇帮路匪","count":4,"sc":"阳光森林","rw":{"gold":122,"items":[]},"lv":7,"tr":["Engerek Çetesine Ceza (1)","Delikanlı, buraya bir katkın olsun isterim. Köyün dışındaki ormanı Engerek Çetesi işgal etti; sıradaki hedefleri Guanlin Kasabası. Buradaki halkın acı çekmesine izin veremem; onları durdurmanın bir yolunu bulmalısın!","Kabul","Engerek Çetesine haddini bildir!","Harika iş, dostum."],"en":["Punish the Viper Gang (1)","Young one, I hope you'll do your part here. The forest outside the village has been taken over by the Viper Gang, and Guanlin Town is their next target. I can't let our people suffer; you must find a way to stop them!","Accept","Teach the Viper Gang a lesson!","Nicely done, friend."]},{"id":81619,"giver":"民兵队长","to":"民兵队长","type":"kill","target":"毒蛇帮精英","count":8,"sc":"阳光森林南","rw":{"gold":68,"items":[["10032",1],["10040",1]]},"lv":13,"tr":["Engerek Çetesine Ceza (2)","Bu sefer Engerek Çetesine ağır bir darbe vurmalıyız. Artık buna gücün yetiyor; beni hayal kırıklığına uğratmayacağına inanıyorum, değil mi?","Kabul","Engerek Çetesine haddini bildir!","Muhteşem, dostum! Artık belleri kırıldı."],"en":["Punish the Viper Gang (2)","This time we must deal the Viper Gang a heavy blow. You're strong enough now; I trust you won't let me down, right?","Accept","Teach the Viper Gang a lesson!","Splendid, friend! That crippled them."]},{"id":81623,"giver":"走私者","to":"走私者","type":"collect","target":"蜘蛛掠夺者","count":5,"sc":"阳光森林北","chance":0.6,"rw":{"gold":202,"items":[]},"lv":10,"tr":["Yağmacının Sırrı","Daha önce… bazı önemli eşyalarımı o lanet Örümcek Yağmacılar kaptı. Bu aslında bir sırdı; böyle mallarım olduğunu kimse bilmesin istiyordum. Sana sorunu çözmek için söylüyorum, sakın etrafa yayma… Pekâlâ, gerçek şu ki o yağmacılar şimdi Güneşli Orman Kuzey'e kaçtı. Onları bul… öldür, içindekileri bana getir.","Kabul","Yoksa hepsini kendine mi sakladın?","Ahh, bu küçük hazineler sonunda elime döndü… İyi ki sen ahmak değerlerini bilmiyorsun. Al ödülünü, haydi git!","Kilitli Kese"],"en":["The Raiders' Secret","Earlier… some important things of mine were stolen by those cursed Spider Raiders. It was supposed to be a secret; I didn't want anyone to know I had such goods. I'm telling you only to get this solved, so don't go spreading it… Well, the truth is those raiders have moved to Sunny Forest North. Find them… kill them, and bring me what they carry.","Accept","Did you keep them for yourself?","Ahh, my little treasures are back in my hands at last… Good thing an idiot like you doesn't know their worth. Take your reward and go!","Locked Pouch"]},{"id":81624,"giver":"走私者","to":"疯子","type":"talk","req":81623,"rw":{"gold":78,"items":[]},"tr":["Uyarı!","Ha, aklıma bir şey geldi: Deli'yi uyar, benden uzak dursun. Bir gün deliliği tutar da sırrımı ağzından kaçırır, kim bilir. Söyle ona, dikkatli olsun!","Kabul","Deli'ye uyarıyı ilet.","(Deli omuz silkiyor ve kıkırdıyor.)"],"en":["A Warning!","Oh, something just occurred to me: warn the Madman to stay away from me. Who knows, one day he might go mad and blurt out my secret. Tell him to watch it!","Accept","Pass the warning on to the Madman.","(The Madman shrugs and giggles.)"],"lv":10},{"id":81629,"giver":"观林镇镇长","to":"杰克医生","type":"talk","rw":{"gold":138,"items":[["30016",5],["30019",5],["30024",1]]},"tr":["Muhtarın Derdi","Son zamanlarda ne oluyor bilmiyorum, sırtım hep sızlıyor; yoksa kötü bir işaret mi bu? Kızım Doktor Jack'e görünmem için başımın etini yiyor ama işlerim o kadar yoğun ki hiç vaktim yok. Durumumu Doktor Jack'e anlatır mısın?","Kabul","Doktor Jack'e muhtarın durumunu anlat.","Sırt ağrısı mı? Hmm, bir düşüneyim."],"en":["The Mayor's Trouble","I don't know what's going on lately, but my back keeps stinging; could it be a bad omen? My daughter keeps nagging me to see Doctor Jack, but I'm too busy with official duties. Could you tell Doctor Jack about my condition?","Accept","Tell Doctor Jack about the mayor's condition.","Back pain? Hmm, let me think."],"lv":10},{"id":81630,"giver":"杰克医生","to":"杰克医生","type":"pickup","node":"魔法草","count":5,"sc":"阳光森林南","req":81629,"rw":{"gold":145,"items":[["30016",5],["30019",5],["30024",1]]},"lv":13,"tr":["Büyülü İksir (1)","Muhtarın sırt ağrısını geçirecek bir büyülü iksir üzerinde çalışmam gerek; malzemesi Güneşli Orman Güney'deki büyü otu. Ama orada bir sürü vahşi hayvan var; bu konuda bana bir tek sen yardım edebilirsin.","Kabul","Haydi büyü otlarını topla; Güneşli Orman Güney'de.","Biraz bekle, iksiri hemen hazırlıyorum.","Büyü Otu"],"en":["Magic Potion (1)","I need to work on a magic potion that will cure the mayor's back pain; the ingredient is the magic herb in Sunny Forest South. But there are many wild beasts there; only you can help me with this.","Accept","Go and gather the magic herbs in Sunny Forest South.","Wait a moment, I'll mix the potion right away.","Magic Herb"]},{"id":81631,"giver":"杰克医生","to":"观林镇镇长","type":"talk","req":81630,"rw":{"gold":28,"items":[["30016",5],["30019",5],["30024",1]]},"tr":["Büyülü İksir (2)","Sonunda bitti; bu iksiri muhtara götür. Onu acısından kurtaracağına söz veriyorum.","Kabul","İksiri muhtara götür.","Oh, sırtım rahatladı! Teşekkür ederim."],"en":["Magic Potion (2)","It's finally done; take this potion to the mayor. I promise it will free him from his pain.","Accept","Take the potion to the mayor.","Oh, my back feels better! Thank you."],"lv":13},{"id":81635,"giver":"疯子","to":"寡妇安娜","type":"talk","rw":{"gold":81,"items":[]},"tr":["Dul Kadına Taziye","Geceleri hep Anna'nın sessizce ağladığını duyuyorum. Ah, çocuğunu da kocasını da vahşi hayvanlar yedi; çok yazık. Git, yardımıma ihtiyacı var mı bir sor; varsa… anlarsın ya. Sakın karıma söyleme.","Kabul","Dul Anna ile konuş.","Deli mi gönderdi seni? Hıh."],"en":["Comfort the Widow","At night I always hear Anna weeping softly. Ah, her child and her husband were both eaten by wild beasts; it's so sad. Go and ask if she needs my help; if she does… you know. Whatever you do, don't tell my wife.","Accept","Talk to the Widow Anna.","The Madman sent you? Hmph."],"lv":13},{"id":81636,"giver":"寡妇安娜","to":"疯子的老婆","type":"talk","req":81635,"rw":{"gold":101,"items":[]},"tr":["Dulun Dileği","O Deli kendi karısıyla ilgilenmiyor da bana mı ilgi gösteriyor! Git, karısına söyle; biz kadınların öyle kolay kandırılmadığını bilsin. Kocam öldü diye bana yanaşmaya çalışmak ha? Asla!","Kabul","Deli'nin karısına anlat.","Neee? O mu?!"],"en":["The Widow's Wish","That Madman doesn't care about his own wife, yet he cares about me! Go and tell his wife; let her know we women aren't so easily fooled. Trying to get close to me because my husband died? Never!","Accept","Tell the Madman's wife.","Whaaat? Him?!"],"lv":10},{"id":81637,"giver":"疯子的老婆","to":"疯子","type":"talk","req":81636,"rw":{"gold":75,"items":[["30024",1]]},"tr":["Kıyamet Koptu","Alçak herif, onu asla affetmeyeceğim! Beni kandırmaya nasıl cüret eder, ona o kadar iyi davrandım! Madem öyle, gününü göstereceğim; buranın meşhur cadısıyım ben! Git, söyle ona, beni bir daha göremeyecek!","Kabul","Deli'ye haberi ver.","Eyvah! Karım duydu mu?!"],"en":["Raging Fury","That scoundrel, I'll never forgive him! How dare he deceive me after all I've done for him! Fine then, I'll show him; I'm the most famous shrew around here! Go and tell him he'll never see me again!","Accept","Give the Madman the news.","Oh no! My wife found out?!"],"lv":13},{"id":81638,"giver":"疯子","to":"疯子的老婆","type":"talk","req":81637,"rw":{"gold":31,"items":[["30024",1]]},"tr":["Karıcığım! Hata Ettim!","Yalvarırım, bana yardım etmelisin; hatamı anladım… Eminim sen bir yolunu bulursun.","Kabul","Deli'nin karısıyla konuş.","Hıh, şimdi mi aklı başına geldi?"],"en":["Darling! I Was Wrong!","Please, you have to help me; I know I was wrong… I'm sure you'll find a way.","Accept","Talk to the Madman's wife.","Hmph, he comes to his senses now?"],"lv":13},{"id":81639,"giver":"疯子的老婆","to":"疯子","type":"talk","req":81638,"rw":{"gold":27,"items":[]},"tr":["Affedilemez","Söyle ona, onu affetmeyeceğim! Ben daha ölmedim, başka kadınların peşine düşmeye nasıl cüret eder!","Kabul","Deli'ye cevabı ilet.","Affetmiyor mu? Ah, ne yapacağım şimdi…"],"en":["Unforgivable","Tell him I won't forgive him! I'm not even dead yet, and he dares to chase other women!","Accept","Take her answer to the Madman.","She won't forgive me? Oh, what do I do now…"],"lv":13},{"id":81640,"giver":"疯子","to":"疯子","type":"collect","target":"蜂蜜仙子","count":10,"sc":"阳光森林东","chance":0.5,"rw":{"gold":122,"items":[]},"lv":18,"tr":["Deli'nin Ricası","Dostum, Güneşli Orman Doğu'ya gitmen lazım; orada bal perileri var. Bir yolunu bul, onlardan tatlı toz al; tatlı yapmak için en iyi malzeme. Karıma nefis bir tatlı hazırlayacağım.","Kabul","Ah, bana mutlaka yardım etmelisin.","Çok teşekkür ederim, velinimetim!","Tatlı Toz"],"en":["The Madman's Request","Friend, I need you to go to Sunny Forest East; there are honey fairies there. Find a way to get sweet powder from them; it's the best ingredient for desserts. I want to make my wife a lovely treat.","Accept","Ah, you simply must help me.","Thank you so much, my benefactor!","Sweet Powder"]},{"id":81641,"giver":"疯子","to":"馋鬼","type":"talk","req":81640,"rw":{"gold":108,"items":[["30024",1]]},"tr":["Tatlı Yapımı","Dostum, paketlediğim bu tatlı tozu oradaki Obur'a ver; mutlaka nefis bir tatlı yapar. Gerçi gizlice atıştıracak ama yeterince malzeme hazırladım. Ha ha.","Kabul","Tatlı tozunu Obur'a götür.","Tatlı toz mu? Mmm, harika!"],"en":["Making Dessert","Friend, give this packed sweet powder to the Glutton over there; he'll make a delicious dessert. He'll sneak a few bites, but I prepared plenty. Ha ha.","Accept","Take the sweet powder to the Glutton.","Sweet powder? Mmm, wonderful!"],"lv":13},{"id":81642,"giver":"馋鬼","to":"馋鬼","type":"talk","count":1,"req":81641,"rw":{"gold":60,"items":[["30024",1]]},"tr":["Çeşni","Hımm, tadı gayet güzel; bir de bana bir porsiyon acılı kanat bulsan mükemmel olur, ha ha ha!","Kabul","Çabuk git gel.","Ha ha, bu tat kusursuz!","Acılı Kızarmış Kanat"],"en":["Seasoning","Mmm, it tastes great; if you could find me a serving of spicy roast wings, it would be perfect, ha ha ha!","Accept","Be quick.","Ha ha, this flavor is simply perfect!","Spicy Roast Wings"],"lv":10},{"id":81645,"giver":"护林游侠","to":"护林游侠","type":"kill","target":"☆精英护卫","count":5,"sc":"阳光森林东","rw":{"gold":150,"items":[["30024",1]]},"lv":18,"tr":["Hattı Yar","Guanlin Kasabası'nda bir hain çıktı: Sadinman kasabanın bilgilerini çaldı, şimdi de Güneşli Orman Doğu'da kim bilir ne çeviriyor. Bunu araştırmanı istiyorum; önce ☆Seçkin Muhafızların hattını yarmalısın.","Kabul","☆Seçkin Muhafızlara dikkat et.","Yardımın için teşekkürler; bu işi Milis Komutanı ile konuşacağım."],"en":["Break the Line","A traitor has appeared in Guanlin Town: Sadinman stole the town's intelligence, and now he's in Sunny Forest East plotting who knows what. I'd like you to investigate; first you must break through the ☆Elite Guards' line.","Accept","Beware of the ☆Elite Guards.","Thank you for your help; I'll discuss this with the Militia Captain."]},{"id":81646,"giver":"疯子","to":"疯子的老婆","type":"talk","rw":{"gold":87,"items":[]},"req":81642,"tr":["Deli'nin Kefareti","Obur tatlıyı bana verdi; neyse ki çok atıştırmamış. Eminim karım beni affedecek; Tanrım, yardım et! Onu mutlaka bizzat eline ver, kahraman!","Kabul","Tatlıyı Deli'nin karısına götür.","Bu tatlı… onun için mi yaptı?"],"en":["The Madman's Atonement","The Glutton gave me the dessert; luckily he didn't eat much of it. I'm sure my wife will forgive me; gods, help me! You must hand it to her personally, hero!","Accept","Take the dessert to the Madman's wife.","This dessert… he made it for me?"],"lv":13},{"id":81647,"giver":"疯子的老婆","to":"疯子","type":"talk","req":81646,"rw":{"gold":35,"items":[["30024",1]]},"tr":["Affet Onu","Onu affettim ama bir dahası yok; bir daha böyle yaparsa boşanırım!!!!","Kabul","Deli'ye müjdeyi ver.","Affetti mi? Yaşasın!"],"en":["Forgive Him","I've forgiven him, but there won't be a next time; if he does this again, I'll divorce him!!!!","Accept","Give the Madman the good news.","She forgave me? Hooray!"],"lv":13},{"id":81709,"giver":"民兵队长","to":"观林镇镇长","type":"talk","rw":{"gold":122,"items":[]},"tr":["Muhtar Değişti","Muhtar eskiden çok yufka yürekli biriydi; asla böyle sert cezalar vermezdi. Dön ve muhtara ceza yöntemine hayran kaldığımı söyle; bir de Güneşli Orman Doğu'daki ☆Engerek Çetesi Kasaplarını ne yapacağımızı sor.","Kabul","Muhtar ne yapacak acaba? Gerçekten değişti mi?","Komutan bu küçük işi bile çözemiyor; iyi ki sen varsın!"],"en":["The Mayor Has Changed","The mayor used to be very soft-hearted; he would never hand out such harsh punishments. Go back and tell the mayor I admire his methods, and ask him what we should do about the ☆Viper Gang Butchers in Sunny Forest East.","Accept","What will the mayor do? Has he really changed?","The captain can't even handle such a small matter; good thing you're here!"],"lv":7},{"id":81710,"giver":"观林镇镇长","to":"民兵队长","type":"kill","target":"☆毒蛇帮虐杀者","count":10,"sc":"阳光森林东","req":81709,"rw":{"gold":203,"items":[["30024",1]]},"lv":18,"tr":["Kasapların Sonu","Milis Komutanı'nın sorusunu hemen cevaplayabilirim; çok basit: Güneşli Orman Doğu'ya git ve onları kasaplıklarına pişman et! Hiç acıma! Kaçsalar da yalvarsalar da ancak kan onları pişman eder! İşin bitince Milis Komutanı ile konuş; bakalım bana hayran kalmış mı.","Kabul","Basit ve etkili; benim yolum budur. Merhamet hiçbir şeyi çözmez.","Demek şüphelerim doğruymuş; muhtarda gerçekten bir tuhaflık var…"],"en":["The End of the Butchers","I can answer the Militia Captain's question right away; it's simple: go to Sunny Forest East and make them regret their butchery! Show no mercy! Whether they flee or beg, only blood will make them repent! When you're done, talk to the Militia Captain and see if he admires me.","Accept","Simple and effective is my way. Mercy solves nothing.","So my suspicions were right; something really is wrong with the mayor…"]},{"id":81711,"giver":"民兵队长","to":"护林游侠","type":"talk","req":81710,"rw":{"gold":85,"items":[]},"tr":["Muhtar Gerçekten Değişti","Muhtar son zamanlarda bir sarsıntı mı geçirdi de böyle aşırı şeyler yapıyor? Git, Orman Korucusu'na sor; o her zaman muhtarın en iyi dostu oldu, bir şey fark etmiş mi bak.","Kabul","Muhtar gerçekten çok tuhaf, hiç anlayamıyorum.","Muhtar son zamanlarda neredeyse kimseyle konuşmuyor."],"en":["The Mayor Has Truly Changed","Has the mayor suffered some setback lately, to do such excessive things? Go and ask the Forest Ranger; he's always been the mayor's best friend; see if he's noticed anything.","Accept","The mayor is really strange; I can't make sense of it.","The mayor has hardly spoken to anyone lately."],"lv":7},{"id":81712,"giver":"护林游侠","to":"兽人医师","type":"talk","req":81711,"rw":{"gold":160,"items":[]},"tr":["Keşke Hastalık Olsa","Muhtar son zamanlarda benimle neredeyse hiç konuşmuyor; umarım sadece hastadır. Koşanat Şehri'ne git ve bir Ork Hekim bul; büyüde usta bu şifacı muhtarın hastalığını iyileştirebilir. Durum acil; \"Mürekkep\"imi bir günlüğüne sana ödünç veriyorum, ne kadar çabuk o kadar iyi!","Kabul","Muhtarın hastalığı ne acaba? Çok tuhaf.","Muhtar benim velinimetim, borcumu ödeyeceğim!"],"en":["I Hope It's Just Illness","The mayor hardly talks to me anymore; I hope he's only ill. Go to Galloping Horse City and find an Orc Healer; that healer, skilled in magic, should be able to cure the mayor. It's urgent; I'll lend you my \"Ink\" for a day, the sooner the better!","Accept","What illness could the mayor have? So strange.","The mayor is my benefactor; I'll repay him!"],"lv":18},{"id":81723,"giver":"炼金师","to":"炼金师","type":"collect","target":"☆☆【欺诈者】迪加","count":1,"sc":"奔马海港","chance":1,"rw":{"gold":160,"items":[["10057",1],["10073",1],["10909",1]]},"req":81722,"lv":25,"tr":["Kristal Küre","Bu iş epey karışık; bir fal bakmam gerekecek. Ama fal kristal kürem çalındı; mutlaka Koşanat Limanı'ndaki o haydutların işi. Kırmızılar giymiş bir cüce gördüm, galiba liderleri; cesedinden kristal küremi geri getir!","Kabul","Kristal kürem… o olmadan bir hiçim…","İşte kristal kürem, sapasağlam; çok teşekkür ederim!","Kristal Küre"],"en":["The Crystal Ball","This matter is rather complicated; I'll need to do a divination. But my crystal ball was stolen; it must be those bandits at Galloping Horse Harbor. I saw a gnome in red who seemed to be their leader; bring my crystal ball back from his corpse!","Accept","My crystal ball… without it I'm useless…","This is my crystal ball, perfectly intact; thank you so much!","Crystal Ball"]},{"id":81724,"giver":"炼金师","to":"炼金师","type":"talk","req":81723,"rw":{"gold":56,"items":[]},"tr":["Fal","Madem kristal küremi geri getirdin, sana bir fala bedava bakayım! Biraz bekle…","Kabul","Merak etme, senden para almayacağım; biraz bekle.","Korkunç bir gerçek… Kabullenmekten başka çaremiz yok…"],"en":["Divination","Since you brought back my crystal ball, I'll do a divination for you for free! Please wait…","Accept","Don't worry, I won't charge you; just a moment.","A terrible truth… we can only accept it…"],"lv":25},{"id":81725,"giver":"炼金师","to":"民兵队长","type":"talk","req":81729,"rw":{"gold":154,"items":[]},"tr":["Tarikat!","Tarikat! Ne korkunç bir durum; daha önce böyle şeyler duymuştum. Yoksa muhtar tarikatın kuklası mı oldu? Bu çok korkunç; kukla yalnızca kalbi olmayan bir cesettir. Guanlin Kasabası da tehlikede. Halkı tedirgin etmemek için gizlice Milis Komutanı'na sor; bakalım ne yapacak.","Kabul","Korkunç bir durum; düşündükçe tüylerim diken diken oluyor!","Muhtarın ruhunu belki de rivayetlerdeki Kalp Hırsızı Büyücü çaldı… Guanlin Kasabası gerçekten tehlikede!"],"en":["The Cult!","A cult! What a terrible situation; I've heard of such things before. Has the mayor become the cult's puppet? That's dreadful; a puppet is just a corpse without a heart. Guanlin Town is in danger too. So as not to alarm the townsfolk, quietly ask the Militia Captain what he'll do.","Accept","A horrifying situation; it makes my skin crawl just thinking about it!","Perhaps the mayor's soul was stolen by the rumored Heart-Stealing Mage… Guanlin Town really is in danger!"],"lv":25},{"id":81726,"giver":"民兵队长","to":"民兵队长","type":"kill","target":"受伤的银鹰战士","count":10,"sc":"草原前线","req":81725,"rw":{"gold":180,"items":[["30024",1]]},"lv":29,"tr":["Gücünü Kanıtla","Görünen o ki tarikatla doğrudan yüzleşmeden bu iş çözülmeyecek. Ama gücün sadece Engerek Çetesine yetiyorsa, tarikata karşı gitmek bir ceset göndermekten farksız olur. Sınavımı kabul et; bakalım yiğit misin korkak mı! Çayır Cephesi'ne git, 10 Yaralı Gümüşkartal Savaşçısı öldür ve gücünü kanıtla!","Kabul","Tarikatla savaşabilecek misin?","Seni küçümsemek benim hatammış."],"en":["Prove Your Strength","It seems we can only solve this by facing the cult directly. But if your strength is only enough for the Viper Gang, going against the cult would be like sending a corpse. Take my test; let's see if you're a hero or a coward! Go to the Prairie Front, kill 10 Wounded Silver Eagle Warriors and prove your strength!","Accept","Can you really fight the cult?","It was my mistake to underestimate you."]},{"id":81728,"giver":"炼金师","to":"炼金师","type":"collect","target":"森林巨魔","count":1,"sc":"巨魔森林","chance":1,"req":81724,"rw":{"gold":161,"items":[]},"lv":28,"tr":["Tuhaf Olaylar","İrade falım hep Trol Ormanı'nda bir engele takılıyor; bu nasıl iş? Üstelik son zamanlarda troller de huzursuz; normalde ot yiyen bu iri yaratıklar kana susadı. Belki muhtar oradaki durumdan endişelendiği için böyle oldu. Onlardan birkaç örnek getir, neler olduğuna bakayım.","Kabul","Trol Ormanı'nda neler oluyor acaba?","Bu ne? Kara bir muska mı? Bu şey ne işe yarıyor?","Şüpheli Nesne"],"en":["Strange Happenings","My will divination is always blocked at the Troll Forest; why is that? And lately the trolls are restless too; these normally plant-eating brutes have become bloodthirsty. Maybe the mayor became like this out of worry about that place. Bring back some samples from them; let me see what's going on.","Accept","What on earth is happening in the Troll Forest?","What's this? A black amulet? What does this thing do?","Suspicious Object"]},{"id":81729,"giver":"炼金师","to":"炼金师","type":"talk","count":1,"req":81728,"rw":{"gold":46,"items":[["30024",1]]},"tr":["Kara Muska","Bence bunu muhtara göstermelisin; ona merak etmemesini, çözümü bulduğumuzu söyle. Bakalım tuhaf hastalığı biraz düzelecek mi.","Kabul","Muhtar bu tuhaf şeyi görünce belki içindeki dert geçer.","Ne?! Bu hiç beklemediğim bir sonuç…","Kara Muska"],"en":["The Black Amulet","I think you should show this to the mayor; tell him not to worry, we've found a solution. Let's see if his strange illness improves.","Accept","Once the mayor sees this strange thing, perhaps his heart will be eased.","What?! I never expected this…","Black Amulet"],"lv":25},{"id":81731,"giver":"民兵队长","to":"观林镇镇长","type":"talk","count":1,"req":81726,"rw":{"gold":108,"items":[["30024",1]]},"tr":["Ruhun Dönüşü","(Bu soğuk şişeye dokunuyorsun; içinde mavi, soğuk bir ışık saçan bir sis var. Sis toplandığında içinde muhtarın acı çeken yüzünü görüyorsun.) ☆Tarikatçılar muhtarı belki de bununla yönetiyordu. Bunu al ve muhtarı kurtar.","Kabul","Artık içim rahat.","Öhö öhö… çok kötüyüm…","Ruh Şişesi"],"en":["The Soul Returns","(You touch the cold bottle; inside is a mist glowing with a cold blue light. As the mist gathers, you see the mayor's tormented face within.) The ☆cultists may have used this to control the mayor. Take it and save him.","Accept","Now I can rest easy.","Cough… I feel awful…","Soul Bottle"],"lv":7},{"id":81732,"giver":"观林镇镇长","to":"观林镇镇长","type":"kill","target":"☆邪教追随者","count":15,"sc":"邪教基地","req":81731,"rw":{"gold":92,"items":[]},"lv":31,"tr":["Kökünü Kazı","Ah, başım çatlıyor; bu süre boyunca sanki ölmüş gibi bulanık bir bilinçle yaşadım… Bu lanet tarikatçılar! Guanlin Kasabası'nın huzuru için, kahraman… yalvarırım, şu tarikatçıları bir an önce yok et!","Kabul","Guanlin Kasabası'nın geleceği için git, şu tarikatçıların kökünü kazı!","Sen her zaman Guanlin halkının kahramanı olacaksın!"],"en":["Wipe Them Out","Ah, my head is pounding; all this time I lived with a clouded mind, as if I'd died… These cursed cultists! For the peace of Guanlin Town, hero… I beg you, wipe out these cultists as soon as you can!","Accept","For the future of Guanlin Town, go and root out these cultists!","You will always be the hero of Guanlin's people!"]},{"id":80020,"giver":"兽人警卫队长","to":"皇家骑士特使","type":"talk","rw":{"gold":58,"items":[["30024",1]]},"tr":["Asıl Suçlu","Onların bir başı var, doğru duydun. Belki bir zamanlar subaymış, kim bilir. Ama şimdi bu kargaşanın kaynağı o; onu ortadan kaldırırsak iş kolaylaşır.","Kabul","Bana bakma; bu sopayla onu döverek öldürmemi mi bekliyorsun?","Başları mı var? Bu iş ilginçleşti."],"en":["The Ringleader","They have a leader, you heard right. Maybe he was once an officer, who knows. But now he is the root of this unrest; take him out and things get simple.","Accept","Don't look at me. Do you expect me to beat him to death with this stick?","A leader? Now this is getting interesting."],"lv":29},{"id":80026,"giver":"奔马城城主","to":"奔马城城主","type":"collect","target":"☆走私者军官","count":1,"sc":"奔马海港","chance":1,"req":80058,"rw":{"gold":68,"items":[["30024",1]]},"lv":25,"tr":["Şehir Beyinin Öfkesi","Belki de bu herifleri fazla şımarttım. Gittikçe azıtıyorlar, ben de aptal yerine konuyorum. Eminim şimdi zayıflığıma gülüyorlardır, lanet olasılar! Git, o subayı gebert ve eşyamı geri getir.","Kabul","Belki de o limanı tamamen ele geçirmem gerek.","Bu şeyin nesi var, kendim çözeceğim.","İlginç Ufak Şey"],"en":["The Lord's Wrath","Perhaps I have been too lenient with these fellows. The bolder they get, the more of a fool I look. I'm sure they are laughing at my weakness right now, curse them! Go, kill that officer and bring my thing back.","Accept","Maybe I should take over that harbor entirely.","I'll figure out what this thing is myself.","Curious Trinket"]},{"id":80054,"giver":"幸运的卡卡","to":"幸运的卡卡","type":"collect","target":"兵痞","count":1,"sc":"阳光草原","chance":1,"rw":{"gold":141,"items":[["30024",1],["30033",10],["30030",10]]},"lv":20,"tr":["Centilmenin İntikamı","İnanabiliyor musun? O başıboş serseri askerler beni, bir centilmeni haraca bağladı! Şu sol gözüme bak; bu morluğu kazara bir yere çarparak edinmediğim belli değil mi? Üstümdeki her şeyi aldılar, Ork kardeşlere hediye edeceğim saç bandı da dahil. Bunun hesabını sormalıyım.","Kabul","Şu lanet göz morluğu nasıl geçecek?","Bir centilmeni soymanın bedeli işte bu.","Saç Bandı"],"en":["A Gentleman's Revenge","Can you imagine? Those wandering soldier thugs extorted me, a gentleman! Look at my left eye; you don't think I got this bruise by bumping into something, do you? They took everything I had, including the hair band I meant to give the Orc siblings. I must have my revenge.","Accept","How do I get rid of this blasted black eye?","That is the price of robbing a gentleman.","Hair Band"]},{"id":80055,"giver":"幸运的卡卡","to":"兽人兄","type":"talk","count":1,"req":80054,"rw":{"gold":76,"items":[["30024",1]]},"tr":["Kardeş Sevgisi","Şu Ork kardeşleri gördün mü? Aralarındaki bağ insanı gerçekten duygulandırıyor. Peki, saç bandını ağabeye ver; sanırım kız kardeşine vereceği hediye buydu.","Kabul","Benimle konuşarak çok şey öğrenirsin, delikanlı.","Saç bandım! Teşekkürler.","Uğurlu Saç Bandı"],"en":["Sibling Love","Have you seen those Orc siblings? The bond between them is truly touching. Well, give the hair band to the brother; I believe this is the gift he wanted to give his sister.","Accept","Talk to me and you'll learn a lot, young one.","My hair band, thank you.","Lucky Hair Band"],"lv":20},{"id":80056,"giver":"战争铁匠","to":"战争铁匠","type":"collect","target":"☆走私者军官","count":5,"sc":"奔马海港","chance":0.6,"rw":{"gold":73,"items":[["30024",1]]},"lv":25,"tr":["Örnek Lazım","Yüksek rütbeli subaylar hep farklı olduklarını göstermek ister; kılıçları gırtlağını kolayca keser. Bunlardan birkaç örnek elde etmek istiyorum; ancak o zaman beylerin acelesine yetişip kaliteli bir parti mal çıkarabilirim.","Kabul","Şu an dövdüğüm şeylerde hep bir eksik var gibi.","Bu kılıçların farkını sen de fark etmişsindir.","Subay Kılıcı"],"en":["I Need Samples","High-ranking officers always like to show they are different; their swords can slit your throat with ease. I would love a few samples, so I can finish a batch of fine goods while those lords keep rushing me.","Accept","Something always seems to be missing from what I forge.","You must have noticed what makes these swords different."]},{"id":80057,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"kill","target":"逃兵队长","count":5,"sc":"阳光草原","req":80020,"rw":{"gold":116,"items":[["30024",1]]},"lv":20,"tr":["Önce Başı Ez","Bu firariler sadece birer kiralık kabadayı. Elebaşlarını öldürürsek beyinsiz kalan kabadayıların icabına bakmak kolay olur.","Kabul","Bir kez karar verdin mi kararlılıkla uygulamalısın.","Gerisini temizlemek artık an meselesi."],"en":["Strike the Head","These deserters are just hired muscle. Kill their leaders, and muscle without a brain is easy to deal with.","Accept","Once you make a decision, carry it out without hesitation.","Mopping up the rest is only a matter of time."]},{"id":80058,"giver":"侏儒商队首领","to":"奔马城城主","type":"talk","rw":{"gold":117,"items":[["30024",1]]},"tr":["İlginç Ufak Şey","Şehir Beyi son zamanlarda her türlü ilginç ufak şeyi topluyor. Bunu bulmak için çok uğraştım ama yolda bir kaçakçı subayı elimden kaptı. Sanırım bunu Şehir Beyi'ne sen söylemelisin.","Kabul","Eşyayı zorla geri almaya cesaretim yok.","Ne! Benim malıma göz dikmeye nasıl cüret ederler!"],"en":["A Curious Trinket","The Lord has lately been collecting all sorts of curious trinkets. I worked hard to find this one, but a smuggler officer snatched it on the road. I think you should tell the Lord.","Accept","I wouldn't dare take it back by force.","What! They dare lay hands on my things!"],"lv":23},{"id":80060,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"pickup","node":"叛军的粮草","count":5,"sc":"银鹰城南","req":81734,"rw":{"gold":75,"items":[]},"lv":31,"tr":["Düşmanın Erzağı","Burası düşmanın gerisi, yiyecek hiç yeterli olmuyor… Yakına Gümüşkartal Şehri'nin yeni bir ikmal kolu gelmiş diye duydum. Git, oradan biraz erzak araklayıver!","Kabul","Erzak çalamazsan aç kalırsın.","Güzel! Bakıyorum da… karnın epey doymuş.","Erzak"],"en":["Eat the Enemy's Grain","We are behind enemy lines here, and food is never enough… I hear a new Silver Eagle supply train has arrived nearby. Go and steal some provisions!","Accept","If you can't steal any food, you'll go hungry.","Nice! You look… rather well fed.","Provisions"]},{"id":80064,"giver":"皇家骑士特使","to":"易燃的货物","type":"talk","req":80060,"rw":{"gold":91,"items":[]},"tr":["Ordugâhı Yak","Bak, bu kükürt, bu da gaz yağı… Ne yapmanı istediğimi anladın mı? Git, bu tutuşturucuları düşman çadırlarının etrafına yerleştir… Sonra bir ok yağmuruyla bu gece onları açık havada yatırırız.","Kabul","Yükü düşman çadırlarının yanına bırak.","(Yanıcı yükü çadırların dibine yerleştirdin.)"],"en":["Burn the Camp","Look, this is sulfur, this is lamp oil… Understand what I want? Go and place these around the enemy tents… then a volley of fire arrows will have them sleeping under the moon tonight.","Accept","Place the cargo next to the enemy tents.","(You set the flammable cargo at the foot of the tents.)"],"lv":20},{"id":80066,"giver":"皇家骑士特使","to":"骑士护卫","type":"talk","count":1,"req":80068,"rw":{"gold":79,"items":[["30024",1],["10130",1],["10137",1]]},"tr":["Bilmemen Gereken Şeyler","Lütfen bu mektubu okumadığını söyle; bazen fazla bilmemek iyidir. Şimdi onu muhafızıma ver, gerisini dert etme. Yine de sana teşekkür borçluyum; en azından onu çöp diye atmadın.","Kabul","Hep beklenmedik şeyler olur.","(Muhafız sana soğukça bakıyor ve tek kelime etmeden mektubu koynuna koyuyor.)","Diga'nın Mektubu"],"en":["Things You Needn't Know","Please tell me you haven't read this letter; sometimes it's better not to know too much. Now hand it to my guard and don't worry about the rest. Still, thank you; at least you didn't throw it away as scrap paper.","Accept","There is always something unexpected.","(The guard looks at you coldly and tucks the letter into his coat without a word.)","Diga's Letter"],"lv":20},{"id":80067,"giver":"城镇公告牌","to":"奔马城城主","type":"collect","target":"☆☆【欺诈者】迪加","count":1,"sc":"奔马海港","chance":1,"rw":{"gold":117,"items":[["30024",1],["30033",10],["30030",10]]},"lv":25,"tr":["Ödül: Kaçakçı Kral","Kaçakçıların asıl lideri \"Dolandırıcı\" Diga tehlikeli bir deli; açgözlü ve kana susamış. Kasabanın güvenliğini ciddi biçimde tehdit ediyor. Kellesini getiren yiğit cömertçe ödüllendirilecek.","Kabul","İstediğimi getirdin mi?","Gözlerine bakılırsa ölümü hiç hazmedememiş.","Diga'nın Kellesi"],"en":["Bounty: The Smuggling Baron","The true leader of the smugglers, \"the Swindler\" Diga, is a dangerous madman, greedy and bloodthirsty. He seriously threatens the town's safety. The hero who brings back his head will be richly rewarded.","Accept","Did you bring what I asked for?","Judging by his eyes, he didn't go willingly.","Diga's Head"]},{"id":80068,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"talk","rw":{"gold":27,"items":[["30024",1]]},"req":80067,"tr":["Gizli Mektup","(Diga'nın üstünden çıkan mektup. Gizli bir yazışmaya benziyor. Onu Kraliyet Şövalye Elçisi'ne götür.)","Kabul","Mektubu elçiye ver.","Bu mektubu nereden buldun?"],"en":["A Secret Letter","(A letter found on Diga. It looks like a private correspondence. Take it to the Royal Knight Envoy.)","Accept","Give the letter to the envoy.","Where did you find this letter?"],"lv":20},{"id":80091,"giver":"皇家骑士特使","to":"皇家炮队技师","type":"talk","req":80064,"rw":{"gold":57,"items":[["30484",5]]},"tr":["Karşı Hamle","Düşmanın kanadına bir mancınık hattı kurdum ama geçen günkü çarpışmada bozuldular. Ele geçirdiğin bu parçaları al, oradaki subayın onları onarmasına yardım et!","Kabul","Parçaları topçu ustasına götür.","Tamam!"],"en":["Countermeasure","I set up a line of catapults on the enemy's flank, but they were damaged in battle the other day. Take these parts you captured and help the officer there repair them!","Accept","Take the parts to the artillery engineer.","All right!"],"lv":20},{"id":80092,"giver":"皇家炮队技师","to":"皇家骑士特使","type":"kill","target":"☆战争巨魔","count":10,"sc":"银鹰城东北","req":80091,"rw":{"gold":188,"items":[["30419",5]]},"lv":32,"tr":["Savaş Makinesi","Gümüşkartal büyücüleri korkunç bir yaratık yarattı: ☆Savaş Trolü. Korku ve acı nedir bilmeyen bu zalim yaratık savaş alanına kan ve ölüm saçıyor. Askerlerimin onu görünce altlarına etmesine dayanamıyorum… Git, 10 ☆Savaş Trolü öldür! Acemiler bunların korkulacak bir şey olmadığını görsün!","Kabul","Trollere meydan okuma, fırsatını bulunca boynunu koparırlar.","Trol kafalarını ordugâhın en yüksek yerine astıracağım; moraller düzelsin."],"en":["War Machine","The Silver Eagle mages have created a terrible creature: the ☆War Troll. This merciless beast knows no fear or pain and spreads blood and death on the battlefield. I can't stand seeing my soldiers wet themselves at the sight of one… Go and kill 10 ☆War Trolls! Show the recruits there is nothing to fear!","Accept","Don't taunt the trolls; they'll bite your neck off at the first chance.","I'll have the troll heads hung atop the camp to lift everyone's spirits."]},{"id":80094,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"kill","target":"☆战斗教官","count":10,"sc":"银鹰城西北","req":81739,"rw":{"gold":61,"items":[["30484",5]]},"lv":34,"tr":["İpleri Kes","Askerler kukladır, general kuklayı oynatan eldir; eli kuklaya bağlayan ise iplerdir. Alt ve orta rütbeli subaylar bu ipin en önemli düğümleri. Onları kes; düşman savaşmadan dağılsın.","Kabul","Düşmanın düzenini bozamazsan örgütlü bir orduyla baş etmek çok zordur.","Güzel, asilerin birbirine girdiğini şimdiden görür gibiyim. Karşı saldırı zamanı geldi."],"en":["Cut the Strings","Soldiers are puppets and the general is the hand that moves them; what links the hand to the puppets are the strings. Junior and mid-rank officers are the key knots in those strings. Cut them, and the enemy will fall apart without a fight.","Accept","If you can't disrupt the enemy's plans, an organized army is very hard to beat.","Good, I can already picture the rebels in chaos. Time to strike back."]},{"id":80096,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"collect","target":"☆银鹰信使","count":1,"sc":"银鹰城西北","chance":1,"req":81760,"rw":{"gold":59,"items":[]},"lv":34,"tr":["Pusu","Çabalarımız sayesinde düşman geri çekiliyor. Yine de son günlerde sık sık görünen düşman ulakları aklımı kurcalıyor. Git, herhangi birini öldür; hangi gizli haberleri taşıdıklarını göreyim.","Kabul","Burada oturup boşa harcadığın zamanda bir savaşın kaderi değişirdi.","Hayır, bu mektubun içeriği korkunç… Büyük bir sırra rastladık galiba…","Asi Mektubu"],"en":["Ambush","Thanks to our efforts the enemy is retreating. Still, those enemy couriers that have been so active lately worry me. Go and kill one of them; let me see what secret intelligence they carry.","Accept","The time you waste sitting here could turn the tide of a battle.","No, this letter's contents are terrible… It seems we have uncovered a great secret…","Rebel Letter"]},{"id":80098,"giver":"皇家骑士特使","to":"国王","type":"talk","req":80096,"rw":{"gold":153,"items":[["10097",1],["10110",1],["10926",1]]},"tr":["Nişan","Önceki savaşlarda çok iyi iş çıkardın. Senden fazla bir şey istemiyorum; krala ve orduya karşı görevini neredeyse eksiksiz yerine getirdin. Savaş sürse de bir ödülü hak ettiğini düşünüyorum: bizzat Kral'ın vereceği bir nişan. Bir de sana… silah arkadaşım demekten onur duyarım.","Kabul","Kral'ın huzuruna çık.","Teşekkür ederim, Majesteleri."],"en":["The Decoration","You did very well in the battles so far. I have little more to ask of you; your duty to the King and the army is all but fulfilled. Though the war goes on, I believe you deserve an honor, granted by the King himself. And allow me the honor of calling you… comrade.","Accept","Go before the King.","Thank you, Your Majesty."],"lv":20},{"id":80266,"giver":"皇家骑士特使","to":"前线斥候","type":"talk","rw":{"gold":149,"items":[["30024",1]]},"tr":["Cepheden Haber","Çayır Cephesi Başkent'e giden tek yol; ama Gümüşkartal asileriyle savaşımız çok uzun sürdü ve bu yol çok tehlikeli hâle geldi. Cephe Gözcüsü'nü bul ve keşif görevini onunla birlikte tamamla.","Kabul","İmparatorluğun senin gibi yiğitlere ihtiyacı var.","Tam da adama ihtiyacım vardı."],"en":["Report from the Front","The Prairie Front is the only road to the Capital, but our war with the Silver Eagle rebels has dragged on and the road has become very dangerous. Find the Frontline Scout and complete the reconnaissance with him.","Accept","The Empire needs heroes like you.","I was just in need of help."],"lv":20},{"id":80269,"giver":"皇家骑士特使","to":"国王特使","type":"talk","req":80266,"rw":{"gold":90,"items":[["30024",1]]},"tr":["İzin İste","Orduya nasıl saldıracağını söyleyebilirim ama genel düzeni ilgilendiren bu kararı ben vermem. Anlasan da anlamasan da bu iş için Kralın Elçisi'nden izin almalısın.","Kabul","Dikkat et, kılıksız insanlardan hiç hoşlanmaz.","Bu, bugün duyduğum en iyi haber."],"en":["Ask for Orders","I could command how the army attacks, but a decision that affects the whole campaign isn't mine to make. Whether you understand or not, you must ask the King's Envoy over there.","Accept","Careful, he doesn't like slovenly people.","That is the best news I've heard all day."],"lv":20},{"id":80270,"giver":"国王特使","to":"皇家骑士特使","type":"talk","req":80269,"rw":{"gold":104,"items":[["30024",1]]},"tr":["Kaçırılmaz Fırsat","Bu kaçırılmaz bir fırsat. Normalde aceleci olan o adamın neden tereddüt ettiğini hiç anlamıyorum. Yaralılar sargılarını sarıp sıcak çorbalarını içip yatana kadar mı bekleyecek? Bu fırsatı kaçırmayın, diyeceğim bu.","Kabul","Bu, asilere ağır bir darbe vurur! En azından ben öyle düşünüyorum.","Bunu bu kadar kararlı söylemesine sevindim."],"en":["A Perfect Opportunity","This is a perfect opportunity. I don't understand why that usually rash fellow hesitates. Does he want to wait until the wounded are bandaged, have had their soup and gone to bed? Don't waste this chance; that's all I have to say.","Accept","This could cripple the rebels! At least, I think so.","I'm glad he said it so decisively."],"lv":20},{"id":80349,"giver":"兽人兄","to":"兽人警卫队长","type":"talk","count":1,"req":80055,"rw":{"gold":34,"items":[["30024",1],["30030",10]]},"tr":["Orkların Ziyafeti","Ah, iyi kalpli yabancı, bana bir iyilik yapar mısın? Bu ziyafeti Muhafız Komutanı'na götür, şu an hiç ayrılamıyorum.","Kabul","Biz Orklar yemekten anlarız, buna hiç şüphe yok.","Mis gibi kokuyor! Harika!","Berbat Ziyafet"],"en":["An Orc Feast","Oh, kind stranger, could you do me a favor? Take this feast to the Guard Captain; I really can't leave right now.","Accept","We Orcs are connoisseurs of food, no doubt about it.","What a smell! Wonderful!","Awful Feast"],"lv":29},{"id":80350,"giver":"国王特使","to":"皇家骑士特使","type":"talk","rw":{"gold":82,"items":[["30024",1]]},"tr":["Küstahlık","Savaş alanındaki bu korkaklar bir savaşçının onurunu hiçe sayıyor; Kral buna çok öfkeli. Git, Şövalye Elçisi'ne sor; bu iş ne âlemde?","Kabul","Buraya sadece onlar için gelmedim.","Firariler konusunda bazı ipuçlarım var."],"en":["Sheer Audacity","These battlefield cowards treat a warrior's honor so lightly; the King is furious. Go and ask the Knight Envoy how this matter is being handled.","Accept","I didn't come here just for them.","I already have some leads on the deserters."],"lv":20},{"id":80351,"giver":"皇家骑士特使","to":"兽人警卫队长","type":"talk","req":80350,"rw":{"gold":67,"items":[["30024",1]]},"tr":["Muhafız Komutanının İpucu","Belli ki bu firarilerin her hareketi planlı. Muhafız Komutanı'nı bul; bu sinsi fareleri benden iyi tanır.","Kabul","Kral yiğit asker topluyor, gidip bakmalısın.","Hmm… Şövalye elçiniz akıllı bir adam."],"en":["The Guard Captain's Lead","Clearly every move these deserters make is planned. Find the Guard Captain; he knows these pesky rats better than I do.","Accept","The King is recruiting heroes; you should go and see.","Hmm… your Knight Envoy is a clever man."],"lv":20},{"id":80417,"giver":"皇家骑士特使","to":"前线斥候","type":"talk","req":80270,"rw":{"gold":55,"items":[["30033",5]]},"tr":["Emre Uy","Saldırın! Yok edilebilecek her gücü yok edin! Bu asilere verilen cezadır; savaşın merkezinden uzak bu yere gelip rahatça yaralarını saracaklarını sanıyorlarsa çok yanılıyorlar.","Kabul","En küçük gecikme bile savaşın gidişatını değiştirir.","Henüz tehlikenin farkında değiller gibi."],"en":["Follow Orders","Attack! Destroy every force that can be destroyed! This is the rebels' punishment; if they think they can lick their wounds in peace far from the front, they are sorely mistaken.","Accept","Even the slightest delay can change the course of the war.","They don't seem to sense the danger yet."],"lv":20},{"id":80475,"giver":"兽人警卫队长","to":"警卫卡鲁","type":"talk","rw":{"gold":90,"items":[["30033",5]]},"tr":["Kardeşin İzi","Benim kadar güçlü olan kardeşim, Şehir Beyi'nin tuhaf merakları yüzünden uzun zamandır Trol Ormanı'nda. Orası et kızartmak için hiç iyi bir yer değil. Onu bulmama yardım et, bak bakalım ne durumda.","Kabul","Trol Ormanı yakın değil dostum; yolda açlıktan ölmemek için yanına biraz yiyecek al.","İnsan, burada ne işin var?"],"en":["Brother's Whereabouts","My brother, as strong as I am, has been in the Troll Forest for a long time because of the Lord's strange hobbies. That's no place for a barbecue. Help me find him and see how he's doing.","Accept","The Troll Forest isn't close, friend; you may want to pack some food so you don't starve on the way.","Human, what are you doing here?"],"lv":29},{"id":80477,"giver":"奔马城城主","to":"奔马城城主","type":"kill","target":"受伤的军犬","count":10,"sc":"草原前线","rw":{"gold":65,"items":[["30033",5]]},"lv":29,"tr":["Hayvanları Temizle","Hayvanlardan nefret ederim! O lanet savaş köpekleri çayırıma kadar geldi. Bir gün hiç fark etmeden şehrin ortasında belirsinler istemem. Sahipleri kim olursa olsun, git temizle şunları.","Kabul","Dünyada neden bu kadar tuhaf yaratık var?","Bilmelisin ki ben temizliği seven bir cüceyim."],"en":["Clear Out Those Animals","I hate animals! Those blasted war dogs have reached my prairie. I don't want them showing up in town when I'm not looking. Whoever their masters are, go and clear them out.","Accept","Why are there so many strange creatures in the world?","You should know I am a gnome who likes things clean."]},{"id":80687,"giver":"兽人警卫队长","to":"兽人警卫队长","type":"kill","target":"☆银鹰斥候","count":10,"sc":"草原前线","rw":{"gold":143,"items":[]},"lv":29,"tr":["Tedbir","Bütün düşmanlar içinde en çok gözcülerden nefret ederim, biliyor musun? Seni uzaktan gözlerler; tam bir savaşçı gibi düello etmeye hazırlandığında yılan gibi kayıp giderler. Son günlerde kasabanın çevresinde sık görünüyorlar. Niyetleri ne bilmiyorum ama sana çorba ısmarlamak olmadığı kesin. Onlara bir ders vermenin zamanı geldi.","Kabul","Yüz yüze gelsek tek yumrukta yere sererdim.","Bu sonuç içimi ferahlattı."],"en":["Planning Ahead","Of all enemies I hate scouts the most, you know? They watch you from afar, and when you're ready to duel them like a warrior, they slip away like snakes. Lately they keep appearing around town. I don't know what they're after, but it's certainly not to buy you soup. Time to teach them a lesson.","Accept","Face to face, I'd knock them down with one punch.","That makes me feel much better."]},{"id":81617,"giver":"奔马城城主","to":"奔马城城主","type":"kill","target":"兽人强盗","count":5,"sc":"阳光草原","rw":{"gold":111,"items":[["30024",1]]},"lv":20,"tr":["Patron Cücelerdir","Dostum, şunu anlaman lazım: bu çayırda Orkların hükmü çoktan tarih oldu, artık sözü cüceler söyler. Ama onuru bu kadar önemseyen o herifler haydutluğa düşer, hiç aklıma gelmezdi. Biraz vakit ayırıp onlara patronun kim olduğunu göster!","Kabul","Ne o? Sakın onları yenemediğini söyleme!","Bilesin, ırkçılık yapmıyorum; bu sadece asayişi korumak için gereken bir iş."],"en":["Gnomes Are the Boss","Friend, understand this: Orc rule over this prairie is long gone; now the gnomes call the shots. Still, I never thought those honor-obsessed fellows would sink to banditry. Take some time to show them who's the boss!","Accept","What? Don't tell me you can't beat them!","Mind you, I'm not prejudiced; it's just what keeping the peace requires."]},{"id":81625,"giver":"奔马城城主","to":"皇家骑士特使","type":"talk","req":81617,"rw":{"gold":161,"items":[["30024",1]]},"tr":["Bitmeyen Dertler","Dağınık haydutlara sert yöntemler işe yarayabilir ama asayişi asıl bozan, insanların firari askerleri. Örgütlü işleri başımı ağrıtıyor. Maymundan türemiş o herifler ne yapıyor umurumda değil, yeter ki burayı tehdit etmesinler. Vaktin varsa git, Şövalye Elçisi'nin ağzını ara. Fazla dolaysız olma, bilirsin onlar böyle şeylerden hoşlanır.","Kabul","Kendi ellerimle pişirdiğim kızartmadan ister misin?","Hmm… seni o ihtiyar mı gönderdi?"],"en":["Endless Troubles","Hard methods might work on scattered bandits, but what truly disturbs the peace are the human deserters. Their organized raids give me headaches. I don't care what those monkey-descended folk are up to, as long as they don't threaten this place. If you have time, go and sound out the Knight Envoy. Don't be too blunt; you know they like it that way.","Accept","Want some roast I cooked myself?","Hmm… that old fellow sent you, didn't he?"],"lv":25},{"id":81633,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"kill","target":"懦弱的逃兵","count":10,"sc":"阳光草原","req":81625,"rw":{"gold":55,"items":[["30024",1]]},"lv":20,"tr":["Hepsini Temizle","Bu korkaklar buraya kaçınca canlarını kurtaracaklarını sanıyor; ne gülünç! Askeri disiplini bozan cezalandırılmalı! Unutma, bu sadece asayiş için değil.","Kabul","Askerin acıma lüksü yoktur.","İyi iş çıkardın; İmparatorluk muhafızlarına katılmaya ne dersin?"],"en":["Leave None Standing","These cowards think fleeing here will save their skins; how laughable! Those who break military discipline must be punished! Remember, this isn't just about keeping the peace.","Accept","A soldier has no room for pity.","Well done. Interested in joining the Imperial Guard?"]},{"id":81634,"giver":"城主秘书","to":"侏儒商队首领","type":"talk","rw":{"gold":46,"items":[["30024",1]]},"tr":["Güzellik Meraklısı","On gün önce cüce tüccardan çok güzel bir kolye ısmarladım ama hâlâ ses yok. Benim için bir sorar mısın?","Kabul","Sence güzel miyim?","Kolye… gerçekten başımı ağrıtan bir mesele."],"en":["Lover of Beauty","Ten days ago I ordered a beautiful necklace from the gnome merchant, but there's still no word. Could you ask about it for me?","Accept","Do you think I'm pretty?","The necklace… a real headache, that one."],"lv":23},{"id":81652,"giver":"侏儒商队首领","to":"侏儒商队首领","type":"collect","target":"马贼斥候","count":1,"sc":"清风草原","chance":1,"req":81634,"rw":{"gold":79,"items":[["30024",1]]},"lv":23,"tr":["Haydutları Soy","Bu iş yüzünden uzun zamandır başım ağrıyor. Kervanım dönüş yolunda at hırsızlarının gözüne takıldı, iki adamımı kaybettim. Kolyenin şimdi onların elinde olduğunu sanıyorum. Geri alabilir misin? Emeğin boşa gitmez!","Kabul","Hepsi çok uyanık herifler.","Bu kadar becerikli olduğunu hiç tahmin etmemiştim.","Kristal Kolye"],"en":["Rob the Robbers","This has been giving me a headache for ages. My caravan was spotted by horse thieves on the way back and I lost two men. I believe the necklace is in their hands now. Can you get it back? You won't go unrewarded!","Accept","They are all very alert fellows.","I never guessed you had such skills.","Crystal Necklace"]},{"id":81653,"giver":"侏儒商队首领","to":"城主秘书","type":"talk","count":1,"req":81652,"rw":{"gold":48,"items":[]},"tr":["Güvenilir Tüccar","Şu şeyi sekretere götür; bu yüzden epey zarar ettim. Başıma gelenlere bak; sence biraz ücret iadesi yapmayı düşünmez misin?","Kabul","Lanet at hırsızları!","Ah! Kolyem, ne kadar da güzel.","Kristal Kolye"],"en":["An Honest Merchant","Take this thing to the secretary; I lost a lot because of it. Look at my misfortune; wouldn't you consider giving me back some of the fee?","Accept","Those cursed horse thieves!","Oh! My necklace, it's so beautiful.","Crystal Necklace"],"lv":23},{"id":81654,"giver":"兽人警卫队长","to":"兽人警卫队长","type":"kill","target":"马贼斥候","count":5,"sc":"清风草原","rw":{"gold":84,"items":[]},"lv":23,"tr":["At Hırsızı Belası","Bu at hırsızları çok azıttı! Böyle giderse Koşanat Şehri'nin ticaretteki yeri sarsılır. Şu an yeterince adamım yok; benim için bir iş yapmak ister misin? Ücreti çok iyi.","Kabul","Bu hırsızlar çok tetikte.","Bu da onlara ancak bir uyarı olur."],"en":["Horse Thief Plague","These horse thieves are far too bold! If this goes on, Galloping Horse City's standing in trade will suffer. I'm short on men right now; want to do a job for me? The pay is very good.","Accept","These thieves are very alert.","That's only a warning to them."]},{"id":81655,"giver":"兽人警卫队长","to":"皇家骑士特使","type":"talk","req":81654,"rw":{"gold":95,"items":[]},"tr":["Yine Firariler","Yine mi firariler?! Lanet alçaklar, neden tek bir yerde durmuyorlar ki hepsini bir ateşte yollayayım. Onlardan bıktım usandım; bu sizin elçinizin halletmesi gereken bir mesele.","Kabul","Şu an tek istediğim biraz et yemek.","Bugün benim için gerçekten berbat bir gün."],"en":["Deserters Again","Deserters again?! Damn scoundrels, why won't they stand in one place so I can send them all off with one fire. I'm sick of them; this is something your envoy should handle.","Accept","Right now all I want is some meat.","Today really is a terrible day for me."],"lv":29},{"id":81656,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"collect","target":"☆逃兵弓箭手","count":10,"sc":"清风草原","chance":0.5,"req":81655,"rw":{"gold":113,"items":[["10047",1],["10065",1],["10906",1]]},"lv":23,"tr":["Silahları Topla","Bazen karanlıkta saklanan katiller daha zor durdurulur. Pekâlâ, sana vereceğim iş için bahane uydurmayacağım: bu çayır mutlak kontrolümüzde olmalı, ne demek istediğimi anlarsın. Görevin kanıtı olarak 10 uzun yay topla.","Kabul","Bazı şeyleri fazla bilmene gerek yok.","Bu silahlar Gümüşkartal hainlerine karşı savaşan yiğitlerin elinde olmalı.","Sağlam Uzun Yay"],"en":["Reclaim the Weapons","Sometimes killers hiding in the dark are harder to stop. Well, I won't make excuses for this job: this prairie must be under our absolute control, you know what I mean. Collect 10 longbows as proof of your work.","Accept","Some things you needn't know too much about.","These weapons belong in the hands of heroes fighting the Silver Eagle traitors.","Sturdy Longbow"]},{"id":81657,"giver":"城主秘书","to":"战争铁匠","type":"talk","rw":{"gold":99,"items":[]},"tr":["Ağabeyimin İzi","Jack'i tanıyor musun? O benim ağabeyim, çok iyi bir insandır. Ama evden ayrılalı çok oldu; son söylediği, demirciden iyi bir silah alacağıydı. Usta bir kılıççıdır. Gidip benim için sorar mısın?","Kabul","Onu çok özledim.","Ha, Jack mi?"],"en":["My Brother's Whereabouts","Do you know Jack? He's my brother, a very good man. But he left home a long time ago; the last thing he said was that he'd buy a good weapon from the blacksmith. He's a fine swordsman. Could you ask around for me?","Accept","I miss him so much.","Oh, Jack?"],"lv":25},{"id":81658,"giver":"战争铁匠","to":"侏儒商队首领","type":"talk","req":81657,"rw":{"gold":128,"items":[]},"tr":["İyi Kalpli Jack","Ha, o yardımsever delikanlıyı diyorsun; gerçekten de uzun zamandır görmedim. Belki askere yazılmıştır, kim bilir. Cüce kervanı Başkent'le Koşanat arasında sık gidip gelir; aradığını onlar söyler.","Kabul","Ne zaman savaş çıksa en meşgul adam benim.","\"Firari\" Jack mi? Umarım aynı kişiden bahsetmiyorsundur."],"en":["Good Old Jack","Ah, you mean that helpful lad; come to think of it, I haven't seen him in a long time. Maybe he joined the army, who knows. The gnome caravan often travels between the Capital and Galloping Horse City; they'll tell you what you want to know.","Accept","Whenever there's a war, I'm the busiest man around.","\"Deserter\" Jack? I hope we're not talking about the same man."],"lv":25},{"id":81659,"giver":"侏儒商队首领","to":"奔马城城主","type":"talk","req":81658,"rw":{"gold":200,"items":[["30024",1]]},"tr":["Firari","Haberleriniz amma da geç geliyor. Jack, İmparatorluğun firarisi; Kral'ın bile bildiği biri. Asilerle karşı karşıya gelinen kritik anda bir okçu bölüğünü alıp kaçtı; ülkesine ihanet etti. Onu bir kez Esinti Çayırı'nda gördüm. Bu haberi Şehir Beyi'ne iletmelisin.","Kabul","Onu yakalamanın ödülü ne kadar biliyor musun?","Jack mi? Kim bu Jack?"],"en":["The Deserter","Your news travels slowly. Jack is a deserter of the Empire, a man even the King knows of. At the critical moment against the rebels, he took a company of archers and left; he betrayed his country. I saw him once on the Breeze Prairie. Perhaps you should tell the Lord.","Accept","Do you know how big the bounty on him is?","Jack? Who is Jack?"],"lv":23},{"id":81660,"giver":"奔马城城主","to":"皇家骑士特使","type":"talk","req":81659,"rw":{"gold":77,"items":[["30024",1]]},"tr":["İnsanların Meselesi","Kim o? Bir insan mı? İnsanların sorunlarıyla ben ilgilenmem. Bana bakma, yapacak çok işim var; bir onur unvanı bile olmayan biri kimin umurunda? Madem insan meselesi, insanların elçisine git.","Kabul","Dünyada beni mutlu eden çok az şey var.","Firari! Pekâlâ!"],"en":["A Human Problem","Who? A human? I don't handle human problems. Don't look at me, I have plenty to do; who cares about someone without even a title of honor? Since it's a human matter, go to the human envoy.","Accept","Very few things in this world make me happy.","The deserter! Very well!"],"lv":25},{"id":81662,"giver":"皇家骑士特使","to":"城主秘书","type":"talk","req":81660,"rw":{"gold":80,"items":[["30024",1]]},"tr":["Ardından Gelenler","İyi bir insan her zaman iyi bir asker olmaz; bunu anlaman lazım, delikanlı. Şimdi o üzgün kızın yüzüne bakmak istemiyorum. Nasıl yaparsan yap, bu işi kapat. Yalan da bazen işe yarar.","Kabul","Bu meseleyi bir an önce hallet.","Ah! Zavallı ağabeyim, lanet at hırsızları!"],"en":["Tying Up Loose Ends","A good man isn't always a good soldier; you must understand that, young one. Now, I don't want to face that grieving girl. Whatever way you choose, put an end to this. Sometimes a lie has its uses.","Accept","Deal with this as soon as possible.","Oh! My poor brother, those cursed horse thieves!"],"lv":20},{"id":81663,"giver":"奔马城城主","to":"奔马城城主","type":"collect","target":"草原鹰","count":5,"sc":"清风草原","chance":0.6,"rw":{"gold":129,"items":[["30024",1]]},"lv":23,"tr":["Rengârenk Tüyler","Esinti Çayırı'na gittiysen o çayır kartallarını da görmüşsündür. Aman Tanrım, o güzel tüyleri bir düşün; elbise yapılsa ne güzel olur! Dostum, biraz altın kazanmak istiyorsan fırsatın geldi.","Kabul","Merak etme, bu sefer kesinlikle borcumu ödeyeceğim.","Hey, acele etme; ben hep toptan ödemeye alışkınım.","Rengârenk Tüy"],"en":["Bright Feathers","If you've been to the Breeze Prairie, you've surely seen those prairie eagles. Oh my, think of their beautiful feathers; what a lovely dress they would make! Friend, if you want to earn some gold, here is your chance.","Accept","Don't worry, this time I'll definitely pay up.","Hey, don't rush; I always pay in one go.","Bright Feather"]},{"id":81664,"giver":"奔马城城主","to":"幸运的卡卡","type":"talk","count":1,"req":81663,"rw":{"gold":200,"items":[]},"tr":["Gizli Hüner","O Kaka denen ihtiyarı neden sevdiğimi biliyor musun? Çünkü her işi bilir; o varken ne aşçıya ne terziye ne eczacıya ihtiyacım var… Biraz daha güçlü olsa şu Ork muhafızlara bile para vermem gerekmezdi; o yeşil derili şişkoların ne kadar çok yediğini bir bilsen! Neyse, bu tüyleri ona ver. Vaktin varsa bir mucizenin doğuşuna kendi gözlerinle tanık olursun.","Kabul","Ah, delikanlı, şimdi paradan bahsetme; görevin daha bitmedi.","Terzilik herkesin harcı değildir.","Bir Deste Tüy"],"en":["A Hidden Talent","Know why I like that old man called Kaka? Because he can do everything; with him I don't need a cook, a tailor or an apothecary… If he were a bit stronger I wouldn't even have to pay those Orc guards; heaven knows how much those green-skinned fatties eat! Anyway, give him these feathers. If you have time, you can witness a miracle being born.","Accept","Oh, young one, don't talk about money now; your task isn't done yet.","Not just anyone can be a tailor.","A Bundle of Feathers"],"lv":25},{"id":81665,"giver":"幸运的卡卡","to":"奔马城城主","type":"talk","count":1,"req":81664,"rw":{"gold":58,"items":[]},"tr":["Parlak Fikir","Bu epey vaktimi aldı; insanın üstüne attığı bir parça bez elbise sayılmaz. Şehir Beyi bunu kime verecek bilmiyorum ama bunun bir erkeğin giyebileceği bir şey olmadığı ortada.","Kabul","Bir centilmen çok yönlü olmalı.","Aha, bu ihtiyarın beni hayal kırıklığına uğratmayacağını biliyordum.","Tüylü Uzun Etek"],"en":["A Brilliant Idea","This took me quite some time; a rag thrown over one's shoulders isn't a garment. I don't know who the Lord means it for, but it's clearly not something a man could wear.","Accept","A gentleman must be versatile.","Aha, I knew the old man wouldn't let me down.","Feather Gown"],"lv":20},{"id":81666,"giver":"奔马城城主","to":"城主秘书","type":"talk","count":1,"req":81665,"rw":{"gold":89,"items":[["30024",1]]},"tr":["Cücenin Aşkı","Kabul etmeliyim ki sekreterim çok güzel bir kız; bu elbiseyi giymeye en layık olan o. Nasıl söyleyeceğimi bilmiyorum; ben bir şehir beyiyim, bu konuda acemi görünmek istemem. Benim adıma çalıştığına göre bu işi güzelce bitirmelisin.","Kabul","Yanı başımda bu kadar güzel bir kız varken nasıl fark etmedim? Affedilmez.","Ah… ne güzel bir elbise.","Tüylü Uzun Etek"],"en":["A Gnome in Love","I must admit my secretary is a beautiful girl; she's the one most fit to wear this dress. I don't know how to say it; I'm a lord, and I don't want to look clumsy about this. Since you work for me, you'd better do this job gracefully.","Accept","Such a beautiful girl right beside me and I never noticed. Unforgivable.","Ah… what a beautiful dress.","Feather Gown"],"lv":25},{"id":81667,"giver":"城主秘书","to":"奔马城城主","type":"talk","req":81666,"rw":{"gold":60,"items":[["30024",1]]},"tr":["Kibar Bir Ret","Şu anki sevincimi kelimelerle anlatamam. Vaktin varsa teşekkürlerimi ona iletir misin? Gerçekten de insanı her an mutlu eden iyi bir ağabey.","Kabul","Bunu giyince eminim çok güzel olacağım.","Ağabey mi? Delikanlı, duymak istediğim cevap bu değildi. İşimi böyle mi görüyorsun… Koca bir öğleden sonramı, beş deste kartal tüyünü harcadın ve bana bu haberi mi getirdin? Pekâlâ, söyleyeyim: benden tek kuruş alamazsın."],"en":["A Gentle Rejection","I can't put my joy into words. If you have time, could you pass on my thanks? He really is a kind big brother who always makes people happy.","Accept","I'm sure I'll look beautiful in it.","Big brother? Young one, that is not the answer I wanted to hear. Is this how you do my work… You wasted my whole afternoon and five bundles of eagle feathers to bring me this news? Well, let me tell you: you won't get a single coin from me."],"lv":25},{"id":81668,"giver":"国王特使","to":"皇家骑士特使","type":"talk","rw":{"gold":132,"items":[]},"tr":["Kral'ın Niyeti","Buraya çayır manzarasını seyretmeye geldiğimi mi sanıyorsun? Seni siyasetten anlamaz budala! Koşanat Şehri şu an çok önemli; bir ittifak kurmak zorundayız. Şövalye Elçisi'ne söyle, o deli cücenin isteklerini elinden geldiğince karşılasın.","Kabul","Keşke kullanabileceğim birkaç akıllı adam olsaydı.","Majestelerinin niyetini anlıyorum."],"en":["The King's Intent","You think I came here to admire the prairie? You political fool! Galloping Horse City holds a key position right now; we must form an alliance. Tell the Knight Envoy to satisfy that mad gnome's demands as far as possible.","Accept","I wish I had some clever people to work with.","I understand His Majesty's intent."],"lv":20},{"id":81670,"giver":"皇家骑士特使","to":"奔马城城主","type":"talk","req":81668,"rw":{"gold":61,"items":[["30024",1]]},"tr":["İstekleri Karşıla","Bu \"elinden geldiğince\"nin sınırı ne bilmiyorum ama şunu söyleyeyim: kendini hazırla; o şehir beyinin sana ne yaptıracağını kimse bilemez. Hazırsan git, onunla görüş.","Kabul","Ne karışık zamanlar.","Siz de ilginç bir ırka benziyorsunuz."],"en":["Meet the Demands","I don't know where \"as far as possible\" ends, but I'll tell you this: brace yourself; nobody knows what that lord will make you do. When you're ready, go and see him.","Accept","Such troubled times.","You seem to be an interesting race too."],"lv":20},{"id":81671,"giver":"奔马城城主","to":"奔马城城主","type":"collect","target":"马贼斥候","count":5,"sc":"清风草原","chance":0.6,"rw":{"gold":114,"items":[["30024",1]]},"lv":23,"tr":["At Hırsızlarının Hazinesi","O at hırsızları Esinti Çayırı'nda uzun zamandır terör estiriyor; eminim çok güzel şeyler yağmalamışlardır. Çalıntı mal sahipsiz maldır; fazla düşünme, bana biraz getir.","Kabul","İnsanlar kendi işlerini bile beceremiyor, başka ne yapabilirler bilmem.","Şu göz alıcı mücevherlere bak.","Çalıntı Mal"],"en":["The Horse Thieves' Loot","Those horse thieves have been running wild on the Breeze Prairie for ages; I'm sure they've plundered plenty of good things. Stolen goods have no owner, so don't think too much and get me some.","Accept","Humans can't even handle their own affairs; I wonder what else they can do.","Look at these dazzling gems.","Stolen Goods"]},{"id":81672,"giver":"奔马城城主","to":"奔马城城主","type":"kill","target":"☆逃兵弓箭手","count":10,"sc":"清风草原","rw":{"gold":102,"items":[]},"lv":23,"tr":["Büyük Firari Temizliği","Bu firariler için aslında bir planım yoktu ama iyiliğimden anlamıyorlar gibi; gördüğün gibi kervanıma el uzatmaya cüret ettiler. Onlara biraz gücümü göstermeliyim; cücelere kolay kolay kafa tutulmaz.","Kabul","İnsanlar kendi işlerini bile beceremiyor, başka ne yapabilirler bilmem.","Sanırım bir süre benzer şikâyetler gelmez."],"en":["The Great Deserter Sweep","I had no plans for these deserters, but they don't seem to appreciate my goodwill; as you saw, they dared to attack my caravan. I must show them some force; gnomes are not easily bullied.","Accept","Humans can't even handle their own affairs; I wonder what else they can do.","I don't think there'll be similar complaints for a while."]},{"id":81673,"giver":"奔马城城主","to":"奔马城城主","type":"collect","target":"☆草原漫游者","count":10,"sc":"野马草原","chance":0.5,"rw":{"gold":138,"items":[["30024",1]]},"lv":24,"tr":["Yılan Eti Ziyafeti","Her yerin canlıları kendine özgüdür; sen hiç şunu yedin mi? Ah, saçmaladığım için kusura bakma; demek istediğim, Yabanat Çayırı'ndaki o lezzetli yılan eti. Tatmak istemez misin? Elbette cevabın ne olursa olsun bana biraz getireceksin.","Kabul","İnsanlar kendi işlerini bile beceremiyor, başka ne yapabilirler bilmem.","Bu gerçekten lezzetli yılan eti mi? Beni kandırmıyorsun, değil mi?","Lezzetli Yılan Eti"],"en":["A Snake Meat Feast","Creatures everywhere have their own special traits; have you ever eaten that? Ah, forgive my rambling; I mean the delicious snake meat on the Wild Horse Prairie. Don't you want a taste? Of course, whatever your answer, you'll fetch me some.","Accept","Humans can't even handle their own affairs; I wonder what else they can do.","Is this really the delicious snake meat? You're not fooling me, are you?","Delicious Snake Meat"]},{"id":81674,"giver":"奔马城城主","to":"皇家骑士特使","type":"talk","rw":{"gold":100,"items":[["30024",1]]},"tr":["Gönlü Hoş","Sen iyi bir insansın; belki de bugün insanların samimiyetini nihayet gördüm. Beni aptal mı sanıyorsun? Elçinizin ne düşündüğünü ayak parmağımla bile bilirim. Ama bunun iyi bir seçim olacağını düşünüyorum; ona fikrimi ilet, senin görevin de bitmiş olur.","Kabul","Karlı dağları görmeyi çok isterim.","Görmek istediğim en iyi sonuç buydu; iyi iş çıkardın, delikanlı."],"en":["Well Satisfied","You're a decent human; maybe today I've finally seen human sincerity. Do you take me for a fool? I could guess what your envoy is thinking with my toes. Still, I think this will be a good choice; pass on my answer to him and your task should be done.","Accept","I'd love to see the snowy mountains.","This is the best outcome I could hope for; well done, young one."],"lv":25},{"id":81675,"giver":"皇家骑士特使","to":"国王特使","type":"talk","req":81674,"rw":{"gold":93,"items":[]},"tr":["Elçiye Bildir","Siyasi meseleleri fazla sorma. Şehir Beyi tavrını belli ettiğine göre bu haberi doğrudan Kralın Elçisi'ne ilet; belki sana yeni talimatları vardır.","Kabul","Yapacak daha çok iş var.","Harika iş çıkardın."],"en":["Report to the Envoy","Don't ask too much about politics. Since the Lord has made his position clear, take this news straight to the King's Envoy; he may have further orders for you.","Accept","There's still much to do.","You did splendidly."],"lv":20},{"id":81676,"giver":"国王特使","to":"国王","type":"talk","req":81675,"rw":{"gold":64,"items":[["10132",1],["10061",1],["10905",1]]},"tr":["Dostluk İttifakı","Bu düzenle Gümüşkartal asileri fazla dayanamaz; yaşam alanları daha da daralacak. Teslim olmaları an meselesi. Bu haberi Majestelerine ilet.","Kabul","Burada halletmem gereken başka işler var.","Gümüşkartal asilerinin sonu yaklaştı."],"en":["A Friendly Alliance","With this arrangement the Silver Eagle rebels won't last long; their room to live will shrink further. Their surrender is only a matter of time. Take this news to His Majesty.","Accept","I must stay to handle other matters.","The end of the Silver Eagle rebels is near."],"lv":10},{"id":81677,"giver":"城主秘书","to":"【斥候】布莱恩","type":"talk","rw":{"gold":109,"items":[["30024",1]]},"tr":["Âşığın Özlemi","Zaman kalbimi kemiriyor; bir süredir aklımdan hep aynı düşünce geçiyor: her şeyi bırakıp Yabanat Çayırı'na, en sevdiğim insanın yanına gitmek. Kabalığımı bağışla ama mümkünse, iyi kalpli yabancı, özlemimi ona iletir misin?","Kabul","Bu işten artık bıktım.","Öhö öhö…"],"en":["A Lover's Longing","Time gnaws at my heart; for a while now one thought keeps coming back: leave everything and go to the Wild Horse Prairie to be with the one I love. Forgive my rudeness, but if you can, kind stranger, would you carry my longing to him?","Accept","I'm tired of this job.","Ahem…"],"lv":10},{"id":81679,"giver":"幸运的卡卡","to":"幸运的卡卡","type":"pickup","node":"蝴蝶草","count":5,"sc":"阳光草原","req":81677,"rw":{"gold":124,"items":[["30024",1]]},"lv":20,"tr":["Doktor Kaka","Tamam tamam, acele ettirme. Güneşli Çayır'da gördüğün o grimsi beyaz otları hatırlarsın. İşte o, kelebek otu; zehre karşı harikadır. Ölmesini istemiyorsan git, biraz topla.","Kabul","Zaman hayattır, delikanlı.","İşte bu, iyi ki yanlış getirmedin.","Kelebek Otu"],"en":["Doctor Kaka","All right, all right, don't rush me. You must remember those grayish-white plants on the Sunny Prairie. That's it, butterfly grass, superb against poison. Go and gather some, unless you want him to die.","Accept","Time is life, young one.","That's the one; good thing you didn't get it wrong.","Butterfly Grass"]},{"id":81680,"giver":"幸运的卡卡","to":"侏儒商队首领","type":"talk","req":81679,"rw":{"gold":127,"items":[["30024",1]]},"tr":["Tüccar Ruhu","Bir düşüneyim; bir de kristal ayıraç lazım olabilir. Adına aldanma, değerli bir büyü eşyası değil; birçok şeyin yapımında kullanılan basit bir katalizör. Tüccarlarda olmalı; cüce kervanına bak. Ama onlara biraz altın vermen gerekebilir.","Kabul","Benim sana verecek param yok.","Önce altınlarını göster, delikanlı."],"en":["Merchant's Nature","Let me think; I may also need a crystal reagent. Don't be fooled by the name, it's no precious magic item, just a simple catalyst used for many things. Merchants should have it; check the gnome caravan. You may need to give them some gold though.","Accept","I have no money to give you.","Show me your gold first, young one."],"lv":20},{"id":81681,"giver":"侏儒商队首领","to":"幸运的卡卡","type":"talk","count":1,"req":81680,"rw":{"gold":61,"items":[]},"tr":["Önemli Ayıraç","Bunu bu yıl ilk kez satıyorum. Dostum, nitrik patlayıcı gibi bir şey yapmıyorsun, değil mi? Öyleyse ağzımı sıkı tutmam için biraz daha altın vermelisin.","Kabul","Daha ister misin? Bende çok var.","Acele etmeliyim; umarım o delikanlı dayanabiliyordur.","Kristal Ayıraç"],"en":["An Important Reagent","This is the first one I've sold this year. Friend, you're not making nitrate explosives or something, are you? If so, you'd better pay a bit more gold for me to keep my mouth shut.","Accept","Need more? I have plenty.","I must hurry; I hope that lad can hold on.","Crystal Reagent"],"lv":23},{"id":81685,"giver":"战争铁匠","to":"战争铁匠","type":"collect","target":"☆草原追猎者","count":5,"sc":"野马草原","chance":0.6,"rw":{"gold":92,"items":[["30024",1]]},"lv":24,"tr":["Güçlü Yay","Orklar kadim bir ırktır; pek çok becerileri insanı imrendirir. O iz sürücüleri öldürebiliyorsan, ellerinden birkaç yay al; belki bir şeyler öğrenirim.","Kabul","Bu kolay iş değil.","Dışarıdan bakınca hiç de özel görünmüyor.","Ork Sert Yayı"],"en":["A Strong Bow","Orcs are an ancient race; many of their crafts are enviable. If you can kill those stalkers, take some of their bows; maybe I can learn something from them.","Accept","That won't be easy.","It doesn't look special from the outside.","Orc Longbow"]},{"id":81686,"giver":"战争铁匠","to":"皇家骑士特使","type":"talk","count":1,"req":81685,"rw":{"gold":130,"items":[["30024",1]]},"tr":["Malı Denet","Kimse yarım günde Ork yayları kadar güçlü bir silah yapamaz; ama Kral'ın çok silaha ihtiyacı var, dikkatle inceleyecek zamanım yok. Bu örneği oradaki Şövalye Elçisi'ne götür, sonuca baksın.","Kabul","Ben şahsen hiç memnun değilim.","Hayal ettiğimden biraz uzak ama yine de çok iyi. Çok sayıda üretebilirsek asilere güçlü bir darbe olur.","Yay Örneği"],"en":["Inspection","Nobody can make a weapon as strong as Orc bows in half a day; but the King needs weapons in great numbers, and I have no time for careful study. Take this sample to the Knight Envoy over there and let him see the result.","Accept","Personally, I'm not satisfied.","It's a bit short of what I imagined, but still very good. If we can mass-produce it, it will be a powerful blow to the rebels.","Bow Sample"],"lv":25},{"id":81687,"giver":"战争铁匠","to":"战争铁匠","type":"kill","target":"港口走私者","count":10,"sc":"奔马海港","rw":{"gold":145,"items":[["30024",1]]},"lv":25,"tr":["İntikam!","O liman artık kaçakçıların mekânı. Lanet olsun, bir zamanlar orada yaşıyordum! Yüzümdeki bu yarayı görüyor musun? Hepsi o kaçakçıların işi! Haydutlar! Karım da onların kılıcıyla can verdi. İntikam almak istiyorum; yardım edersen ödülün cömert olur.","Kabul","Keşke onları kendi ellerimle öldürebilsem.","Bu sonu çoktan beklemeleri gerekirdi."],"en":["Revenge!","That harbor is smuggler territory now. Damn it, I used to live there! See this scar on my face? All the smugglers' doing! Bandits! My wife also died by their swords. I want revenge; help me and you'll be well paid.","Accept","I wish I could kill them myself.","They should have seen this end coming."]},{"id":81688,"giver":"战争铁匠","to":"战争铁匠","type":"collect","target":"☆走私者军官","count":1,"sc":"奔马海港","chance":1,"req":81687,"rw":{"gold":123,"items":[]},"lv":25,"tr":["İntikam!","Ak Güvercin Yüreği… Bir zamanlar aramızdaki aşkın simgesi olan bir kolyeydi; hep takardı. (Yüzünü kapatıp ağlıyor) Onu anabileceğim tek şey o. Haydutlar peşimizdeyken kaybettim; bu kadar güzel bir şey mutlaka başlarına sunulmuştur. Ne olur onu geri getir.","Kabul","O haydutların elinde kalmasına asla izin vermemeliyim.","Güzel gülüşünü yeniden görür gibiyim.","Ak Güvercin Yüreği"],"en":["Revenge!","The Heart of the White Dove… a necklace that once symbolized our love; she always wore it. (He covers his face and weeps.) It's the only thing I have to remember her by. I lost it while the bandits were chasing us; something so beautiful must have been offered to their leaders. Please bring it back.","Accept","I must never let it stay in those bandits' hands.","It's as if I can see her lovely smile again.","Heart of the White Dove"]},{"id":81690,"giver":"奔马城城主","to":"兽人警卫队长","type":"talk","rw":{"gold":112,"items":[["30024",1]]},"tr":["Korkunç Haydutlar","Ogreler! Bunlar sıradan haydut değil; canını alırlar, geriye cesedin bile kalmaz. Yabanat Çayırı'nda dolaştıklarını duydum. Lanet olsun, burası kasabaya hiç de uzak değil; muhafızlar nerede, bu herifler hiçbir şey yapmıyor mu? Git, onları bul!","Kabul","Adlarını anmak bile insanı titretiyor.","Bu gerçekten kafa yoran bir mesele."],"en":["Terrible Bandits","Ogres! These are no ordinary bandits; they take your life and not even your corpse remains. I hear they roam the Wild Horse Prairie. Damn, that's not far from town; where are the guards, don't those fellows do anything? Go and find them!","Accept","Even hearing their name makes one tremble.","That's truly a troublesome matter."],"lv":25},{"id":81691,"giver":"兽人警卫队长","to":"兽人警卫队长","type":"kill","target":"☆食人魔强盗","count":10,"sc":"野马草原","req":81690,"rw":{"gold":89,"items":[["30024",1]]},"lv":24,"tr":["Ogreleri Temizle","Genç yiğit, bu zorlu bir görev; reddetmekte tamamen haklısın, çünkü sonuçlardan biri onlara yem olmak. Ama belki de iyi bir seçimdir: bu canavarları bile öldürebilirsen seni korkutabilecek ne kalır ki?","Kabul","Doğuştan çok güçlüdürler.","Sonunda rahat bir nefes alabilirim."],"en":["Purge the Ogres","Young hero, this is a hard task; you'd be fully right to refuse, since one possible outcome is ending up as their meal. But perhaps it's a fine choice: if you can kill even these monsters, what could ever frighten you?","Accept","They are born with tremendous strength.","At last I can breathe easy."]},{"id":81692,"giver":"兽人警卫队长","to":"奔马城城主","type":"talk","req":81691,"rw":{"gold":45,"items":[]},"tr":["Huzur Bozmayın","Daha ne bekliyorsun? Bu müjdeli haberi hemen Şehir Beyi'ne ilet; keyfi yerine gelir, belki bir de ödül alırsın.","Kabul","Bu çayır hep böyle karmakarışık.","Aha, çayırımda böyle canavarlara asla izin vermem."],"en":["Keep the Peace","What are you waiting for? Take this heartening news to the Lord right away; it'll put him in a fine mood, and you may even get a reward.","Accept","This prairie is always such a mess.","Aha, I'll never allow such monsters on my prairie."],"lv":29},{"id":81693,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"kill","target":"港口走私者","count":5,"sc":"奔马海港","rw":{"gold":103,"items":[["30024",1]]},"lv":25,"tr":["Savunmaya Destek","Görünüşe bakılırsa kasabanın savunması pek güçlü değil. Daha çok kâr için kaçakçılar haydutluğa da başlayabilir; aslında şimdiden haydutlar. İnisiyatifi onlara bırakmamalıyız; içlerine korku salmalıyız.","Kabul","Bu kaçakçılar acımasız herifler.","Sapasağlam döneceğini hiç düşünmemiştim."],"en":["Help the Defense","It seems the town's defenses aren't very strong. For greater profit, the smugglers may turn to banditry; in fact, they already are bandits. We mustn't let them take the initiative; we must put fear into them.","Accept","These smugglers are ruthless fellows.","I didn't expect you to come back in one piece."]},{"id":81694,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"kill","target":"☆走私者军官","count":5,"sc":"奔马海港","req":81693,"rw":{"gold":147,"items":[["10054",1],["10070",1],["10908",1]]},"lv":25,"tr":["Kilit Adamlar","Sen de görüyorsundur, hep emir veren birkaç kilit adam var. Tahmin ettiğin gibi, o subaylar onların liderleri; farklı işlere baksalar da sıradan kabadayılardan çok daha üstteler. Bu subayları öldür; geride kalan kabadayılar darmadağın olur.","Kabul","Dikkatli ol, bu subayların kılıç ustalığı fena değil.","Kalıp o şaşkın hâllerini izlemeliydin."],"en":["Key Figures","Surely you can see there are always a few key figures giving orders. As you guessed, those officers are their leaders; though they handle different jobs, they rank far above the common thugs. Kill these officers, and the thugs left behind will scatter like sand.","Accept","Careful, these officers are skilled swordsmen.","You should have stayed to watch their panicked faces."]},{"id":81695,"giver":"侏儒商队首领","to":"侏儒商队首领","type":"collect","target":"☆食人魔强盗","count":10,"sc":"野马草原","chance":0.5,"rw":{"gold":61,"items":[["10659",1]]},"lv":24,"tr":["Kusturun Onları!","Ah! Lanet ogreler! Bütün mallarım gitti; kervanıma saldırmaya cüret ettiler. Zavallı altınlarım, küçük hazinelerimin hepsini yağmaladılar; hepsini kusmaları gerek!","Kabul","Şimdi tam bir fukarayım.","Çok şükür, mallar neredeyse eksiksiz.","Cüce Malı"],"en":["Spit It Out!","Oh! Damned ogres! All my goods are gone; they dared to raid my caravan. My poor gold, all my little treasures plundered; they must spit it all out!","Accept","I'm a pauper now.","Thank goodness, the goods are nearly all here.","Gnome Goods"]},{"id":81696,"giver":"侏儒商队首领","to":"幸运的卡卡","type":"talk","count":1,"req":81695,"rw":{"gold":153,"items":[]},"tr":["Sahte mi Gerçek mi?","Bak dostum, şu yakuta bak! Bu kadar büyüğünü hiç görmemiştim; ama içimden bir ses sahte diyor, bu kadar şanslı olduğumu hatırlamıyorum. Git, Kaka'ya bunun gerçek olup olmadığını sor.","Kabul","O şanslı ihtiyar bundan fazlasını da bilir.","Farklı bir yakut mu?","Kocaman Yakut"],"en":["Real or Fake?","Look, friend, look at this ruby! I've never seen one so big; but something tells me it's fake, I don't recall being this lucky. Go and ask Kaka whether it's genuine.","Accept","That lucky old man knows more than that.","A different kind of ruby?","Huge Ruby"],"lv":23},{"id":81697,"giver":"幸运的卡卡","to":"侏儒商队首领","type":"talk","count":1,"req":81696,"rw":{"gold":74,"items":[]},"tr":["Eşsiz Mücevher","Gerçekten nadir bir taş; daha önce bu boyutta olanını hiç görmedim. Şu rengine bak (konuşurken taşı dikkatle evirip çeviriyor); bu gerçek, eminim! Git ona söyle, zengin oldu.","Kabul","Bunu yontan ustaya nereden bulduğunu bizzat sormak isterdim.","Aha! Gerçekmiş; bir hırsız bunu Kral'ın tacından sökmüş olabilir diye bile düşünüyorum.","Kocaman Yakut"],"en":["A Superb Gem","Truly a rare stone; I've never seen one this size before. Look at its color (he turns the gem carefully as he speaks); it's genuine, I'm sure! Go and tell him he's rich.","Accept","I'd love to ask the jeweler who cut it where he got it.","Aha! Genuine; I even suspect some thief pried it off the King's crown.","Huge Ruby"],"lv":20},{"id":81698,"giver":"侏儒商队首领","to":"皇家骑士特使","type":"talk","count":1,"req":81697,"rw":{"gold":70,"items":[["30024",1]]},"tr":["Sıradan Bir Hediye","Ama bunu satın aldığımı hiç hatırlamıyorum; belki de gerçekten çalıntıdır. Pekâlâ, çok yazık ama başımı belaya sokmak istemem. Hey dostum, bunu sizin elçiye götürüp göstersen iyi olur.","Kabul","Umarım bu sadece benim kuruntumdur.","Bu bana tanıdık geliyor.","Kocaman Yakut"],"en":["An Ordinary Gift","But I don't recall buying this at all; maybe it really is stolen goods. Well, it's a pity, but I don't want trouble. Hey friend, you'd better show this to your envoy.","Accept","I hope it's just my imagination.","This looks familiar."],"lv":23},{"id":81699,"giver":"皇家骑士特使","to":"破烂的包裹","type":"talk","req":81698,"rw":{"gold":41,"items":[["30024",1]]},"tr":["Şüphe","Bu şey gerçekten çok tanıdık geliyor. Onu bulduğun yere git, iyice bak; belki başka ipuçları bulursun.","Kabul","Bu nadir bir yakut.","(Yırtık bohçanın üstünde altın renkli küçük bir yazı var gibi: Onurlu Kont Andfell)"],"en":["Suspicion","This thing really looks familiar. Go back to where you found it and look carefully; maybe you'll find other clues.","Accept","This is a rare ruby.","(There seems to be a line of small golden letters on the tattered bundle: Honorable Count Andfell)"],"lv":20},{"id":81701,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"pickup","node":"散落的物资包","count":5,"sc":"野马草原","req":81699,"rw":{"gold":115,"items":[]},"lv":24,"tr":["Erzakı Topla","Sanırım bu, Kont Andfell'in ailesinin arma taşı. Ticarete ve altına düşkün o zavallı kont, sonunun bir ogrenin midesi olacağını hiç düşünmemiştir; bu sefer parayla çözememiş. Ne acı bir ironi. Pekâlâ, kontun eşyaları bundan ibaret değildir; çayırda iyice dolaş ve dağılmış ne varsa geri getir.","Kabul","Bence çayırda dağılmış daha çok şey var.","Bunların hepsi değerli şeyler.","Erzak Çantası"],"en":["Recover the Supplies","I believe this is the family crest stone of Count Andfell. That poor count, so fond of trade and gold, never imagined he'd end up in an ogre's belly; this time money couldn't solve his problem. What irony. Well, the count's belongings surely don't end here; roam the prairie and bring back everything scattered about.","Accept","I think there's much more scattered across the prairie.","These are all valuable things.","Supply Pack"]},{"id":81702,"giver":"皇家骑士特使","to":"宰相","type":"talk","req":81701,"rw":{"gold":127,"items":[["10658",1]]},"tr":["Vekâlet","Böyle karışık bir dönemde ordusu olmayan bir kontun ölümünün bir etkisi olmaz; ama en azından bunu sadece sen ve ben bilmemeliyiz. Benim yerime Başkent'e git ve haberi Vezir'e ilet.","Kabul","Bu iş için kendim gitmek istemem.","Ruhu huzur bulsun."],"en":["Acting on My Behalf","In such turbulent times, the death of a count without an army won't change much; but at least this shouldn't stay between you and me. Go to the Capital on my behalf and tell the Chancellor.","Accept","I'd rather not make this trip myself.","May his soul rest in peace."],"lv":20},{"id":81713,"giver":"兽人医师","to":"兽人医师","type":"talk","rw":{"gold":130,"items":[["30024",1]]},"tr":["Elimden Geleni Yapacağım","Bir yıl önce Güneşli Orman'da yaban domuzlarının saldırısına uğradım; muhtar öne atılıp beni kurtardı. O benim velinimetim; şimdi hasta, elimden gelen her şeyi yapacağım! Anlattıklarına göre bir düşüneyim, planı nasıl yürüteceğiz.","Kabul","Bir dakika, daha karar vermedim…","Buldum!"],"en":["All Out","A year ago I was attacked by wild boars in the Sunny Forest, and the mayor stepped in and saved me. He's my benefactor; now he's ill, and I'll do everything I can! Based on what you've told me, let me think about how we'll proceed.","Accept","Wait, I haven't decided yet…","I've got it!"],"lv":20},{"id":81714,"giver":"兽人医师","to":"兽人医师","type":"pickup","node":"阳光果","count":3,"sc":"阳光草原","req":81713,"rw":{"gold":192,"items":[["10586",1]]},"lv":20,"tr":["Güneş İksiri","Güneşli Çayır'a git ve biz Orkların en sevdiği güneş meyvesinden topla; bu meyve insana yeni hayat ve cesaret verir. Biraz getir; belki muhtarın tuhaf hastalığını iyileştirir! Ork kahramanları onu korusun!","Kabul","Güneş meyvesinin etkisi seni şaşırtacak!","İşte bu altın sarısı meyveler, tam ihtiyacımız olan.","Güneş Meyvesi"],"en":["Sunshine Potion","Go to the Sunny Prairie and gather sun fruit, the favorite of us Orcs; it brings new life and courage. Bring some; maybe it will cure the mayor's strange illness! May the Orc heroes protect him!","Accept","The sun fruit's power will amaze you!","These golden fruits are exactly what we need.","Sun Fruit"]},{"id":81715,"giver":"兽人医师","to":"兽人医师","type":"collect","target":"兽人强盗","count":1,"sc":"阳光草原","chance":1,"req":81714,"rw":{"gold":118,"items":[["10656",1]]},"lv":20,"tr":["Gümüş Kupa","Az önce bir grup Ork haydut büyülü iksir yaptığım kabı kaptı. Kendi soydaşlarını bile soyuyorlar! Affedilmez; kabım mutlaka birinin üstündedir, hemen geri getir.","Kabul","Bu haydutlar çok alçak! Orkların onurunu ayaklar altına aldılar!","Artık güneş iksirini yapabiliriz!","Gümüş Kupa"],"en":["The Silver Cup","Just now a band of Orc bandits stole the vessel I use for magic potions. They even rob their own kin! Unforgivable. My vessel must be on one of them; hurry and get it back.","Accept","These bandits are despicable! They've lost all Orc dignity!","Now we can make the sunshine potion!","Silver Cup"]},{"id":81716,"giver":"兽人医师","to":"兽人医师","type":"talk","count":1,"req":81715,"rw":{"gold":86,"items":[["30024",1]]},"tr":["Muhtara Dene","Hazırladığım güneş iksirini al ve Guanlin Kasabası muhtarına kullan; bakalım tuhaf hastalığını iyileştirecek mi.","Kabul","Güneş iksiri güneş meyvesinin özünü emdi, kesin işe yarar!","Etkisi olmadı mı? Bunu hiç beklemiyordum.","Güneş İksiri"],"en":["Try It on the Mayor","Take the sunshine potion I made and use it on the mayor of Guanlin Town; let's see if it cures his strange illness.","Accept","The sunshine potion has absorbed the essence of the sun fruit; it's sure to work!","No effect? I didn't expect that.","Sunshine Potion"],"lv":20},{"id":81717,"giver":"兽人医师","to":"兽人医师","type":"talk","req":81716,"rw":{"gold":53,"items":[]},"tr":["İşe Yaramadı mı?","Ne? Hiç mi etkisi olmadı? Üstelik muhtar sana bağırdı mı? Demek hastalığı artık hiç beklemeye gelmez! Başka bir tarif düşüneyim, biraz bekle.","Kabul","Bir düşüneyim…","Tamam, artık halkımızın gizli tarifine başvurma zamanı."],"en":["No Effect?","What? No effect at all? And the mayor yelled at you? Then his illness can't wait any longer! Let me think of another recipe; wait a moment.","Accept","Let me think…","Right, now it's time to use our people's secret recipe."],"lv":20},{"id":81718,"giver":"兽人医师","to":"兽人医师","type":"collect","target":"草原鹰","count":4,"sc":"清风草原","chance":0.6,"req":81717,"rw":{"gold":119,"items":[["10657",1]]},"lv":23,"tr":["Yeni Tarif","Eski kitaptaki tarife göre gidebiliriz: önce 4 damla çayır kartalı gözyaşı topla; kartal cesaret ve gücü simgeler. Eski kayıtlara göre Ork cesaret iksiri hastanın ruhunu tedavi ederek onu iyileştirir.","Kabul","Cesaret iksiri ruhun yaralarını iyileştirir; bu sefer kesin işe yarar!","Güzel, tam istediğim bu!","Çayır Kartalı Gözyaşı"],"en":["A New Recipe","We can follow the recipe from the old book: first collect 4 drops of prairie eagle tears; the eagle stands for courage and vigor. According to the old records, the Orc courage potion cures the sick by healing the soul.","Accept","The courage potion heals the wounds of the soul; this time it can't fail!","Good, that's exactly what I need!","Prairie Eagle Tear"]},{"id":81719,"giver":"兽人医师","to":"兽人医师","type":"collect","target":"☆草原漫游者","count":3,"sc":"野马草原","chance":0.6,"req":81718,"rw":{"gold":151,"items":[]},"lv":24,"tr":["Yardımcı Malzeme","Bu kartal gözyaşları çok sert görünüyor; birinin üstüne dökülse sonu düşünülemez… Velinimetime zarar vermek istemem. Şimdi Yabanat Çayırı'na git ve biraz yılan safrası getir; bu sert gözyaşlarını yumuşatmamız gerek.","Kabul","Tarifin işe yarayacağına inanıyorum!","Artık her şey hazır.","Yılan Safrası"],"en":["Extra Ingredients","These eagle tears look very potent; if they were splashed on someone, it would be unthinkable… I don't want to hurt my benefactor. Now go to the Wild Horse Prairie and bring some snake bile; we need to temper these fierce tears.","Accept","I firmly believe the recipe will work!","Now everything is ready.","Snake Bile"]},{"id":81720,"giver":"兽人医师","to":"兽人医师","type":"talk","count":1,"req":81719,"rw":{"gold":110,"items":[["30024",1]]},"tr":["Cesaret Aşıla","Yaptığım bu ruh arındırıcı iksire halkımızın biraz cesareti de lazım. Koşanat Şehri'ndeki en yiğit Orka git, iksire cesaretini katsın; bence Muhafız Komutanı en iyi seçim.","Kabul","Cesaret iksiri gerçekten mucizevi.","Sonunda bitti.","Cesaret İksiri"],"en":["Infuse Courage","This soul-cleansing potion I made still needs some of our people's courage. Go to the bravest Orc in Galloping Horse City to infuse it with courage; I think the Guard Captain is the best choice.","Accept","The courage potion is truly miraculous.","Finally, it's done.","Courage Potion"],"lv":20},{"id":81721,"giver":"兽人医师","to":"兽人医师","type":"talk","req":81720,"rw":{"gold":137,"items":[["30024",1]]},"tr":["Muhtara Yeniden Dene","Ork cesaret iksiri muhtarı mutlaka kendine getirir! Hemen Guanlin Kasabası'na git; muhtarın hastalığını iyileştirebilirsen ilk iş bana haber ver. Ork kahramanları onu korusun.","Kabul","Hı hı.","……"],"en":["Try the Mayor Again","The Orc courage potion will surely bring the mayor back to his senses! Go to Guanlin Town at once; if it cures the mayor's illness, let me know first thing. May the Orc heroes protect him.","Accept","Mm-hm.","……"],"lv":20},{"id":81722,"giver":"兽人医师","to":"炼金师","type":"talk","req":81721,"rw":{"gold":145,"items":[["30024",1]]},"tr":["Hastalık Değil mi?","Yine mi işe yaramadı? Bu iş çok tuhaf… Ork cesaret iksiri her hastalığı iyileştirir; yoksa muhtar hasta değil mi? Yoksa büyüye mi uğradı? Git, Guanlin Kasabası'ndaki simyacıya sor; çok şey görmüş geçirmiştir.","Kabul","Gerçekten tuhaf.","Sen de muhtar için mi geldin? Ben de bu işi araştırıyorum."],"en":["Not an Illness?","Still no use? This is very strange… The Orc courage potion cures any illness; could it be the mayor isn't sick? Could he be under a spell? Go and ask the alchemist in Guanlin Town; he has seen a great deal.","Accept","Strange indeed.","You've come about the mayor too? I'm looking into this as well."],"lv":20},{"id":81734,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"talk","rw":{"gold":35,"items":[]},"tr":["Kral ve Dük","Kraliyet Şövalye Elçisi'ni dinle.","Kabul","Kral ile Gümüşkartal Dükü aslında üvey kardeşlerdir. Şimdiki Kral tahta çıkınca aralarındaki çekişme büyüdü… sonra bir de prenses meselesi yüzünden…","İşte böyle."],"en":["The King and the Duke","Listen to the Royal Knight Envoy.","Accept","The King and the Silver Eagle Duke are half-brothers. When the current King took the throne, their rivalry deepened… and then, because of the princess…","And that is how it is."],"lv":20},{"id":81735,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"kill","target":"☆☆【族长】迪莫","count":1,"sc":"银鹰城东北","req":80092,"rw":{"gold":109,"items":[["30024",1]]},"lv":32,"tr":["Korucu Lideri","Gümüşkartal Şehri'nin bir başka korucu reisi Gümüşkartal Şehri Kuzeydoğu'da. Çevik korucularıyla ordumuza sık sık baskın yapıyor! Önce başı ez; git, işini bitir!","Kabul","Korucu birlikleri… düşündükçe başım ağrıyor…","Harika! Çok teşekkür ederim!"],"en":["The Ranger Leader","Another ranger chieftain of Silver Eagle City is in Silver Eagle City Northeast. He often raids our army with his nimble rangers! Strike the head first; go and end his life!","Accept","The ranger troops… thinking about them gives me a headache…","Excellent! Thank you so much!"]},{"id":81739,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"collect","target":"银鹰城剑斗士","count":5,"sc":"银鹰城西北","chance":0.6,"req":81735,"rw":{"gold":118,"items":[]},"lv":34,"tr":["Keskin Kılıç","Başkent ordusu mükemmelliği hedefler; zırhlarımızı delebilecek bir silahın var olmasına asla izin veremeyiz! Gümüşkartal kılıç dövüşçüleri bu silahları taşıyor; cesetlerinden bu kılıçları getir, bizim olsun…","Kabul","Her güzel şey bizim olmalı!","Evet, işte bu kılıç! Gerçekten jilet gibi keskin!","Keskin Kılıç"],"en":["Keen Blade","The Capital's army strives for perfection; we can't allow a weapon that can pierce our armor to exist! The Silver Eagle swordfighters carry such weapons; bring these swords back from their corpses for our use…","Accept","All good things should be ours!","Yes, this is the sword! It's incredibly sharp!","Keen Blade"]},{"id":81740,"giver":"奔马城城主","to":"警卫卡鲁","type":"talk","rw":{"gold":96,"items":[["30024",1]]},"tr":["Başka Bir Renk","Bunlar ilginç şeyler ama tek renkle bir işe yaramaz. Yoksa bütün trollerin boynuzları aynı renk mi? Bildiğim böyle değil. Dön ve ona söyle, bana başka renklerden de getirsin.","Kabul","Belki de o şanslı ihtiyarı çağırmalıyım.","Peki, bunu zaten tahmin etmiştim."],"en":["Another Color","These are interesting things, but one color alone won't do. Are all troll horns the same color? That's not what I know. Go back and tell him to get me some of other colors.","Accept","Maybe I should call that lucky old man.","Fine, I saw this coming."],"lv":25},{"id":81745,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"kill","target":"☆☆【伯爵】克拉克","count":1,"sc":"银鹰城西北","req":80094,"rw":{"gold":136,"items":[]},"lv":34,"tr":["Çayırdaki Kont","☆☆【Kont】Clark kılıç ustasıdır ve Gümüşkartal ailesinin en güçlü reisidir. Yanında hep usta kılıççı muhafızlar dolaştırdığını duydum. Dostlarını da al, onu öldür; Gümüşkartal Dükü buna çok şaşıracak, belki korkudan altına bile eder, ha ha!","Kabul","Gümüşkartal Dükü'ne büyük bir hediye göndereceğiz!","Bu his gerçekten harika!"],"en":["The Count of the Prairie","☆☆【Count】Clark is a master swordsman and the strongest chieftain of the Silver Eagle family. I hear he always has skilled sword guards with him. Bring your friends and kill him; the Silver Eagle Duke will be stunned, maybe even wet himself in fear, ha ha!","Accept","We'll send the Silver Eagle Duke a big present!","That feels great!"]},{"id":81746,"giver":"皇家骑士特使","to":"战争铁匠","type":"talk","req":81745,"rw":{"gold":102,"items":[["30024",1]]},"tr":["Keskin Kılıç Malzemesi","Koşanat Şehri'nin çevresi uçsuz bucaksız çayırlar; savaş silahı yapacak malzeme yok denecek kadar az. Cepheye ikmal de azaldı; git, Savaş Demircisi'ne ne yapacağımızı sor.","Kabul","Savaş Demircisi zor zamanlarımızda hep kilit rol oynar.","Hm, Kraliyet Şövalye Elçisi o \"keskin kılıç\"tan seri üretim istemiyor muydu? Bir yolu var!"],"en":["Material for the Keen Blade","Galloping Horse City is surrounded by endless prairie; materials for war weapons are scarce. Supplies from the rear are running low too; go and ask the War Blacksmith what we should do.","Accept","The War Blacksmith always plays a key role when we're in trouble.","Hm, didn't the Royal Knight Envoy want to mass-produce that \"keen blade\"? I have a way!"],"lv":20},{"id":81747,"giver":"战争铁匠","to":"侏儒商队首领","type":"talk","req":81746,"rw":{"gold":72,"items":[]},"tr":["İyi Kılıç Var","Cüce Kervan Başı iyi dostumdur; seni benim gönderdiğimi söylersen belki yardım eder. Ama cimriliğiyle meşhurdur!","Kabul","Cüce Kervan Başı her yere gidip gelir, mutlaka bir yolunu bulur.","Madem Savaş Demircisi gönderdi, sana yardım edeceğim!"],"en":["A Good Sword","The Gnome Caravan Leader is a good friend of mine; if you say I sent you, he might help. But he's famously stingy!","Accept","The Gnome Caravan Leader travels everywhere; he'll surely find a way.","Since the War Blacksmith sent you, I'll help you!"],"lv":25},{"id":81748,"giver":"侏儒商队首领","to":"战争铁匠","type":"collect","target":"☆觅血妖刀","count":5,"sc":"罪恶庭院","chance":0.6,"req":81747,"rw":{"gold":155,"items":[]},"lv":10,"tr":["Hm, Stokta Var","Oo! Demek seni elçi gönderdi! Ne? Cüceler cimri diyen kim! Bu ırkımıza hakaret! O keskin kılıç malzemesi bende stokta var! Hepsini sana hediye ediyorum! Yalnız… kısa süre önce bir grup ☆tarikatçı onları kaptı; o herifler çok korkunç! Peki, geri alabilirsen senin olsun!","Kabul","O tarikatçılar çok çirkin; onlara yol verdim de uğraşmadım.","O cimri cücenin bunları sana bedava vereceği hiç aklıma gelmezdi; gerçek bir mucize.","Kırık Demir Parçası"],"en":["Hm, I Have Stock","Oh! So the envoy sent you! What? Who says gnomes are stingy! That's an insult to our race! I have those keen blade materials in stock! I'll give them all to you! Only… not long ago a band of ☆cultists stole them; those fellows are terrifying! Well, if you can get them back, they're yours!","Accept","Those cultists are really ugly; I just let them be.","I never thought that stingy gnome would really give them to you for free; a true miracle.","Broken Iron Chunk"]},{"id":81757,"giver":"皇家骑士特使","to":"皇家骑士特使","type":"collect","target":"☆银鹰碎颅者","count":10,"sc":"草原前线","chance":0.5,"rw":{"gold":120,"items":[["30024",1]]},"lv":29,"tr":["Üstün İşçilik","Bazen o asilerin hazinedarlarını çok kıskanıyorum; ellerinde harcayacak bol altın var. Bu yüzden savaşçıları hep en iyi miğferleri takar. Paramız buna yetmiyorsa en azından yağmalayabiliriz. Ama önce o kafa kırıcıları susturman gerek.","Kabul","Onları konuşarak miğferlerini sana uslu uslu vermeye ikna edersen ona da itirazım yok.","Şu parlak zırhlara bak; giyen bir daha çıkarmak ister mi?","Gümüşkartal Savaş Miğferi"],"en":["Fine Craftsmanship","Sometimes I really envy those rebel treasurers; they always have plenty of gold to spend. That's why their warriors always wear the best helmets. If money holds us back, at least we can plunder. But first you must silence those skullcrushers.","Accept","I don't mind if you talk them into handing over their armor nicely.","Look at this shiny armor; who would ever take it off once it's on?","Silver Eagle War Helm"]},{"id":81758,"giver":"奔马城城主","to":"奔马城城主","type":"collect","target":"☆巨魔摧毁者","count":10,"sc":"巨魔森林","chance":0.5,"rw":{"gold":133,"items":[]},"lv":28,"tr":["Sıcak Giysiler","Hava gittikçe soğuyor, lanet olsun; cüceler kışı seven yaratıklar değildir. Hey, cebimden biraz altın almak ister misin? Ondan önce Trol Ormanı'na gidip o yok edicilerden biraz yele toplamalısın; ondan bir palto yaptırmak istiyorum.","Kabul","O şey soğuğa karşı çok dayanıklıdır.","Sadece elimde tutarken bile soğuğu hissetmiyorum.","Trol Yelesi"],"en":["Warm Clothes","It's getting colder and colder, damn it; gnomes are not creatures who love winter. Hey, want to take some gold from my pocket? Before that, go to the Troll Forest and collect some mane from those destroyers; I want a coat made of it.","Accept","That stuff is very resistant to cold.","Just holding it, I don't feel the cold at all.","Troll Mane"]},{"id":81759,"giver":"奔马城城主","to":"观林镇镇长","type":"talk","count":1,"req":81758,"rw":{"gold":173,"items":[["30024",1]]},"tr":["Şehir Beyinin Hediyesi","Geçenlerde Guanlin Kasabası muhtarından bir mektup aldım; bana gençliğimde Guanlin'de geçen günleri hatırlattı. O zaman ben de sizin muhtarınız da gençtik, tıpkı şimdi senin gibi. Güzel ve mutlu zamanlardı… Bak yine gevezelik ediyorum; demek istediğim, o yelelerden fazladan bir giysi çıktı. Onu muhtara götür; o yaşta soğuktan çok korkar.","Kabul","Gençlik bir servettir.","İlginç bir adam, değil mi?","Sıcak Kışlık Giysi"],"en":["The Lord's Gift","Recently I received a letter from the mayor of Guanlin Town; it reminded me of my youth in Guanlin. Back then your mayor and I were young, just like you are now. Those were good and happy times… There I go rambling again; what I mean is, those manes made one coat too many. Take it to the mayor; at his age he must fear the cold.","Accept","Youth is a treasure.","He's an interesting fellow, isn't he?","Warm Winter Coat"],"lv":25},{"id":81760,"giver":"战争铁匠","to":"皇家骑士特使","type":"talk","req":81748,"rw":{"gold":58,"items":[["30024",1]]},"tr":["Tam Kapasite Üretim","Dön ve Kraliyet Şövalye Elçisi'ne bildir: arka cephe hazır, hemen tam kapasite üretime geçiyoruz!","Kabul","İçi rahat olsun, elimizden geleni yapacağız!","Güzel! Cepheden saldırıya hazırlanın!"],"en":["Full Production","Go back and report to the Royal Knight Envoy: the rear is ready, and we're moving to full production at once!","Accept","Tell him to rest easy; we'll give it our all!","Good! Prepare for a frontal assault!"],"lv":25}];
  for (const q of Q) {
    const s = E ? q.en : q.tr, to = trName(q.to), sc = q.sc ? trName(q.sc) : '', mon = q.target ? trName(q.target) : '';
    q.title = s[0]; q.text = s[1]; q.ok = s[2]; q.wait = s[3]; q.done = s[4]; if (s[5]) q.item = s[5];
    q.goal = q.type === 'kill' ? (E ? `Kill ${q.count} ${mon} in ${sc}, then talk to ${to}.` : `${sc}: ${q.count} ${mon} öldür, sonra ${to} ile konuş.`)
      : q.type === 'collect' ? (E ? `Collect ${q.count} ${q.item} from ${mon} in ${sc}, then talk to ${to}.` : `${sc}: ${mon} canavarlarından ${q.count} ${q.item} topla, sonra ${to} ile konuş.`)
      : q.type === 'pickup' ? (E ? `Gather ${q.count} ${q.item} in ${sc}, then talk to ${to}.` : `${sc}: ${q.count} ${q.item} topla, sonra ${to} ile konuş.`)
      : q.item ? (E ? `Take the ${q.item} to ${to}.` : `${q.item} eşyasını ${to} kişisine götür.`)
      : (E ? `Talk to ${to}.` : `${to} ile konuş.`);
    delete q.tr; delete q.en; QUESTS.push(q);
  }
})();
